  function decodeBase64Utf8(payload) {
    var raw = atob(payload);
    if (window.TextDecoder) {
      try {
        var bytes = new Uint8Array(raw.length);
        for (var i = 0; i < raw.length; i += 1) {
          bytes[i] = raw.charCodeAt(i);
        }
        return new TextDecoder('utf-8').decode(bytes);
      } catch (decoderError) {}
    }
    try {
      return decodeURIComponent(escape(raw));
    } catch (error) {
      try {
        var escaped = '';
        for (var j = 0; j < raw.length; j += 1) {
          var hex = raw.charCodeAt(j).toString(16);
          escaped += '%' + ('00' + hex).slice(-2);
        }
        return decodeURIComponent(escaped);
      } catch (fallbackError) {
        return raw;
      }
    }
  }

  function injectPortfolioStatic() {
    if (window.__portfolioStaticInjected) return;
    window.__portfolioStaticInjected = true;

    var css = decodeBase64Utf8(__portfolioCssPayload);
    var html = decodeBase64Utf8(__portfolioHtmlPayload);

    var style = document.createElement('style');
    style.setAttribute('data-portfolio-static', 'css');
    style.textContent = css;
    document.head.appendChild(style);

    document.body.innerHTML = html;
  }

  injectPortfolioStatic();
