// Pointer mode: real mouse/fine pointers get the custom cursor; touch remains touch-safe on mobile and hybrids.
const desktopPointerQuery = window.matchMedia?.('(any-pointer: fine)');
const SYNTHETIC_MOUSE_WINDOW = 1600;

function isDesktopPointerEnvironment() {
  return Boolean(desktopPointerQuery?.matches);
}

let hasFinePointer = isDesktopPointerEnvironment();
let attractorSuppressed = false;
let lastTouchAt = 0;
let lastInputType = hasFinePointer ? 'mouse' : 'touch';

// Cursor state is intentionally initialized before syncPointerEnvironment() runs.
// Some media-query/resize callbacks can fire while the script is still booting.
var cRing = document.getElementById('curRing');
var cDot  = document.getElementById('curDot');
var mx = -100, my = -100, rx = -100, ry = -100;
var cursorLoopRunning = false;
var cursorFrameId = 0;
var customCursorSuppressed = false;
const CUSTOM_CURSOR_SUPPRESS_SELECTOR = [
  '.ai-guide-form',
  '.ai-guide-answer',
  '.ai-guide-message',
  '.ai-guide-message-scroll',
  '#aiGuideAnswerText',
  '.footer-form .ff-field',
  'input',
  'textarea',
  'select',
  '[contenteditable="true"]'
].join(', ');

const attractorInputs = {
  mouse: createAttractorInput(),
  touch: createAttractorInput()
};
const inputCaptureOptions = { passive: true, capture: true };
const ATTRACTOR_READY_DELAY = 0.5;

function createAttractorInput() {
  return {
    x: -999,
    y: -999,
    lastX: -999,
    lastY: -999,
    idleTime: 0,
    isIdle: false,
    stoppedTime: 0,
    lastAt: 0,
    seen: false
  };
}

function syncPointerEnvironment() {
  hasFinePointer = isDesktopPointerEnvironment();
  const isTouchOnlyTools = !hasFinePointer;
  const isUsingTouch = isTouchOnlyTools || lastInputType === 'touch';
  document.documentElement.classList.toggle('touch-only-tools', isTouchOnlyTools);
  document.documentElement.classList.toggle('using-touch', isUsingTouch);
  document.body.classList.toggle('touch-only-tools', isTouchOnlyTools);
  document.body.classList.toggle('using-touch', isUsingTouch);
  if (typeof syncCustomCursorState === 'function') syncCustomCursorState();
}

if (desktopPointerQuery?.addEventListener) {
  desktopPointerQuery.addEventListener('change', syncPointerEnvironment);
} else if (desktopPointerQuery?.addListener) {
  desktopPointerQuery.addListener(syncPointerEnvironment);
}
syncPointerEnvironment();

function isLikelySyntheticMouseEvent(e) {
  if (!e) return true;
  if (e.pointerType && e.pointerType !== 'mouse') return true;
  if (e.sourceCapabilities?.firesTouchEvents) return true;
  if (!lastTouchAt) return false;
  return performance.now() - lastTouchAt <= SYNTHETIC_MOUSE_WINDOW;
}

function isRealMouseEvent(e) {
  if (!hasFinePointer) return false;
  return !isLikelySyntheticMouseEvent(e);
}

function canUseMouseCursorEvent(e) {
  return isRealMouseEvent(e);
}

function setCursorGlowTarget(type, x, y) {
  if (!Number.isFinite(x) || !Number.isFinite(y)) return;
  cursorGlow.inputType = type;
  cursorGlow.targetX = x;
  cursorGlow.targetY = y;
  if (cursorGlow.x < -900 || cursorGlow.y < -900) {
    cursorGlow.x = x;
    cursorGlow.y = y;
  }
  cursorGlow.active = true;
  requestStarfieldInputFrame();
}

function releaseCursorGlow() {
  cursorGlow.active = false;
  requestStarfieldInputFrame();
}

function resetCursorGlow() {
  glowBrightness = 0;
  cursorGlow.x = -999;
  cursorGlow.y = -999;
  cursorGlow.targetX = -999;
  cursorGlow.targetY = -999;
  cursorGlow.size = 0;
  cursorGlow.opacity = 0;
  cursorGlow.active = false;
}

function drawCursorGlow(motionOff) {
  if (motionOff) {
    resetCursorGlow();
    return;
  }

  const targetSize = cursorGlow.active
    ? (cursorGlow.inputType === 'touch' ? 74 : 58)
    : 0;
  const targetOpacity = cursorGlow.active
    ? (cursorGlow.inputType === 'touch' ? 0.34 : 0.42)
    : 0;

  if (cursorGlow.active) {
    cursorGlow.x = cursorGlow.targetX;
    cursorGlow.y = cursorGlow.targetY;
    cursorGlow.size += (targetSize - cursorGlow.size) * 0.3;
    cursorGlow.opacity += (targetOpacity - cursorGlow.opacity) * 0.22;
    glowBrightness += (1 - glowBrightness) * 0.2;
  } else {
    // Fade mainly by size first; opacity follows after the glow has collapsed.
    cursorGlow.size *= 0.84;
    const opacityFade = cursorGlow.size > 18 ? 0.965 : 0.82;
    cursorGlow.opacity *= opacityFade;
    glowBrightness *= 0.86;
  }

  if (cursorGlow.size < 0.7 && cursorGlow.opacity < 0.01) {
    cursorGlow.size = 0;
    cursorGlow.opacity = 0;
    return;
  }

  if (cursorGlow.x < -900 || cursorGlow.y < -900) return;

  const glowSize = Math.max(1, cursorGlow.size * (0.84 + glowBrightness * 0.16));
  const glowOpacity = Math.max(0, Math.min(0.65, cursorGlow.opacity));
  const g = sfx.createRadialGradient(cursorGlow.x, cursorGlow.y, 0, cursorGlow.x, cursorGlow.y, glowSize);
  g.addColorStop(0, `rgba(220, 240, 255, ${glowOpacity})`);
  g.addColorStop(0.42, `rgba(100, 150, 255, ${glowOpacity * 0.45})`);
  g.addColorStop(1, 'rgba(61, 111, 255, 0)');
  sfx.fillStyle = g;
  sfx.beginPath();
  sfx.arc(cursorGlow.x, cursorGlow.y, glowSize, 0, Math.PI * 2);
  sfx.fill();
}

function requestStarfieldInputFrame() {
  if (isPartialMotionDisabled()) return;
  lastStarfieldDrawAt = 0;
  scheduleStarfieldFrame();
}

function suppressAttractorAtCurrentFrame() {
  attractorSuppressed = true;
  releaseCursorGlow();
  requestStarfieldInputFrame();
}

function setAttractorInput(type, x, y) {
  if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
  const input = attractorInputs[type];
  const now = performance.now();
  input.x = x;
  input.y = y;
  input.stoppedTime = 0;
  input.idleTime = 0;
  input.isIdle = false;
  input.lastAt = now;
  input.seen = true;
  lastInputType = type;
  attractorSuppressed = false;

  if (type === 'touch') {
    lastTouchAt = now;
    document.documentElement.classList.add('using-touch');
    document.body.classList.add('using-touch');
  } else {
    document.documentElement.classList.remove('using-touch');
    document.body.classList.remove('using-touch');
  }

  setCursorGlowTarget(type, x, y);
  return true;
}

function activateMouseInput(e) {
  if (!canUseMouseCursorEvent(e)) return false;
  if (shouldSuppressCustomCursor(e.target)) {
    suppressAttractorAtCurrentFrame();
    return false;
  }
  return setAttractorInput('mouse', e.clientX, e.clientY);
}

function getTouchPointFromEvent(e) {
  const changed = e.changedTouches;
  const active = e.touches;
  if ((e.type === 'touchstart' || e.type === 'touchmove') && active?.length) {
    return active[active.length - 1];
  }
  if (changed?.length) return changed[changed.length - 1];
  if (active?.length) return active[active.length - 1];
  return null;
}

function activateTouchInputAt(x, y) {
  return setAttractorInput('touch', x, y);
}

function activateTouchInput(e) {
  if (shouldSuppressCustomCursor(e.target)) {
    suppressAttractorAtCurrentFrame();
    return false;
  }
  const touch = getTouchPointFromEvent(e);
  if (!touch) return false;
  return activateTouchInputAt(touch.clientX, touch.clientY);
}

function activateTouchPointerInput(e) {
  if (e.pointerType === 'mouse') return false;
  if (shouldSuppressCustomCursor(e.target)) {
    suppressAttractorAtCurrentFrame();
    return false;
  }
  return activateTouchInputAt(e.clientX, e.clientY);
}

document.addEventListener('mousemove', activateMouseInput, inputCaptureOptions);
document.addEventListener('mousedown', activateMouseInput, inputCaptureOptions);
document.addEventListener('mouseover', activateMouseInput, inputCaptureOptions);
document.addEventListener('pointermove', e => {
  if (e.pointerType === 'mouse') activateMouseInput(e);
  else activateTouchPointerInput(e);
}, inputCaptureOptions);
document.addEventListener('pointerdown', e => {
  if (e.pointerType === 'mouse') activateMouseInput(e);
  else activateTouchPointerInput(e);
}, inputCaptureOptions);

// Touch events for mobile
document.addEventListener('touchstart', activateTouchInput, inputCaptureOptions);
document.addEventListener('touchmove', activateTouchInput, inputCaptureOptions);
document.addEventListener('touchend', activateTouchInput, inputCaptureOptions);
document.addEventListener('touchcancel', activateTouchInput, inputCaptureOptions);
document.addEventListener('touchend', releaseCursorGlow, inputCaptureOptions);
document.addEventListener('touchcancel', releaseCursorGlow, inputCaptureOptions);
document.addEventListener('pointerup', e => {
  if (e.pointerType && e.pointerType !== 'mouse') releaseCursorGlow();
}, inputCaptureOptions);
document.addEventListener('pointercancel', e => {
  if (e.pointerType && e.pointerType !== 'mouse') releaseCursorGlow();
}, inputCaptureOptions);

function updateAttractorIdle(input) {
  if (!input.seen) return;

  if (input.x === input.lastX && input.y === input.lastY) {
    input.idleTime += 0.2;
    input.stoppedTime += 0.2;
    if (input.idleTime > 0.3) {
      input.isIdle = true;
    }
  } else {
    input.lastX = input.x;
    input.lastY = input.y;
    input.idleTime = 0;
    input.isIdle = false;
    input.stoppedTime = 0;
  }
}

// Check if the latest mouse/touch point is idle
setInterval(() => {
  updateAttractorIdle(attractorInputs.mouse);
  updateAttractorIdle(attractorInputs.touch);
}, 200);

function getReadyAttractor() {
  if (attractorSuppressed) return null;

  const latest = attractorInputs[lastInputType];
  if (
    latest?.seen &&
    (!latest.isIdle || latest.stoppedTime <= ATTRACTOR_READY_DELAY)
  ) {
    return null;
  }

  return Object.entries(attractorInputs)
    .filter(([, input]) => (
      input.seen &&
      input.isIdle &&
      input.x > -999 &&
      input.stoppedTime > ATTRACTOR_READY_DELAY
    ))
    .sort((a, b) => b[1].lastAt - a[1].lastAt)[0]?.[1] ?? null;
}

function scheduleStarfieldFrame() {
  if (starfieldFrameId !== null) return;
  starfieldFrameId = requestAnimationFrame(drawSF);
}

function drawStaticStarfield() {
  if (starfieldFrameId !== null) {
    cancelAnimationFrame(starfieldFrameId);
    starfieldFrameId = null;
  }
  lastStarfieldDrawAt = 0;
  drawSF(performance.now());
}

function drawSF(t) {
  starfieldFrameId = null;
  const motionOff = isPartialMotionDisabled();
  if (!motionOff && t - lastStarfieldDrawAt < STARFIELD_FRAME_MS) {
    scheduleStarfieldFrame();
    return;
  }
  lastStarfieldDrawAt = t;

  sfx.clearRect(0, 0, W, H);
  if (motionOff) {
    comets.length = 0;
    attractorSuppressed = false;
  }
  
  // Draw nebula clusters
  const bgNebWidth = Math.min(W, 1700);
  const bgNebOffsetX = (W - bgNebWidth) / 2;
  const bgNebHeight = Math.min(H, 1500);
  const bgNebLift = H > 1500 ? 100 : 0;
  nebs.forEach(n => {
    const bgNebX = bgNebOffsetX + n.x * bgNebWidth;
    const bgNebY = n.y * bgNebHeight - bgNebLift;
    const g = sfx.createRadialGradient(bgNebX, bgNebY, 0, bgNebX, bgNebY, n.r);
    g.addColorStop(0, n.c); g.addColorStop(1, 'rgba(0,0,0,0)');
    sfx.fillStyle = g;
    sfx.beginPath(); sfx.arc(bgNebX, bgNebY, n.r, 0, Math.PI*2); sfx.fill();
  });
  
  // Draw falling comets with elegant trails
  if (!motionOff) for (let i = comets.length - 1; i >= 0; i--) {
    const c = comets[i];
    c.x += c.vx;
    c.y += c.vy;
    c.life -= 0.008; // Smooth fade
    
    if (c.life <= 0) {
      comets.splice(i, 1);
      continue;
    }
    
    const screenX = c.x * W;
    const screenY = c.y * H;
    const lifeAlpha = Math.pow(c.life, 1.2); // Smooth curve fade
    
    // Calculate trail direction (opposite to velocity) - MUCH LONGER
    const trailDist = 650 * lifeAlpha; // Very long visible trail
    const trailEndX = screenX - c.vx * trailDist * 80;
    const trailEndY = screenY - c.vy * trailDist * 80;
    
    // Get RGB components
    const [r, g, b] = c.color.trail;
    
    // Draw long gradient trail with multiple layers for smooth blur effect
    const trailGradient = sfx.createLinearGradient(screenX, screenY, trailEndX, trailEndY);
    trailGradient.addColorStop(0, `rgba(${r}, ${g}, ${b}, ${lifeAlpha})`);
    trailGradient.addColorStop(0.05, `rgba(255, 210, 120, ${lifeAlpha * 0.85})`);
    trailGradient.addColorStop(0.12, `rgba(255, 190, 100, ${lifeAlpha * 0.72})`);
    trailGradient.addColorStop(0.2, `rgba(255, 170, 85, ${lifeAlpha * 0.6})`);
    trailGradient.addColorStop(0.32, `rgba(255, 150, 70, ${lifeAlpha * 0.42})`);
    trailGradient.addColorStop(0.5, `rgba(230, 120, 55, ${lifeAlpha * 0.25})`);
    trailGradient.addColorStop(0.7, `rgba(210, 100, 45, ${lifeAlpha * 0.12})`);
    trailGradient.addColorStop(0.9, `rgba(190, 80, 40, ${lifeAlpha * 0.04})`);
    trailGradient.addColorStop(1, 'rgba(170, 70, 35, 0)');
    
    sfx.strokeStyle = trailGradient;
    sfx.lineWidth = Math.max(5.5, (c.size * 3.2 + Math.max(0, c.size - 3) * 1.6) * lifeAlpha);
    sfx.lineCap = 'round';
    sfx.lineJoin = 'round';
    sfx.shadowColor = `rgba(255, 140, 80, ${lifeAlpha * 0.5})`;
    sfx.shadowBlur = 18 + Math.max(0, c.size - 3) * 22;
    sfx.shadowOffsetX = 0;
    sfx.shadowOffsetY = 0;
    sfx.beginPath();
    sfx.moveTo(screenX, screenY);
    sfx.lineTo(trailEndX, trailEndY);
    sfx.stroke();
    sfx.shadowColor = 'rgba(0,0,0,0)';
    sfx.shadowBlur = 0;
    
    // Draw glowing halo around comet
    const [hr, hg, hb] = c.color.glow;
    const haloGradient = sfx.createRadialGradient(screenX, screenY, 0, screenX, screenY, c.size * 12);
    haloGradient.addColorStop(0, `rgba(${hr}, ${hg}, ${hb}, ${lifeAlpha * 0.5})`);
    haloGradient.addColorStop(0.3, `rgba(${hr}, ${hg}, ${hb}, ${lifeAlpha * 0.15})`);
    haloGradient.addColorStop(1, 'rgba(255, 150, 80, 0)');
    sfx.fillStyle = haloGradient;
    sfx.beginPath();
    sfx.arc(screenX, screenY, c.size * 12, 0, Math.PI * 2);
    sfx.fill();
    
    // Draw bright comet core
    const [cr, cg, cb] = c.color.core;
    const coreGradient = sfx.createRadialGradient(screenX, screenY, 0, screenX, screenY, c.size * 4);
    coreGradient.addColorStop(0, `rgba(${cr}, ${cg}, ${cb}, ${lifeAlpha})`);
    coreGradient.addColorStop(0.5, `rgba(255, 200, 100, ${lifeAlpha * 0.6})`);
    coreGradient.addColorStop(1, 'rgba(255, 180, 100, 0)');
    sfx.fillStyle = coreGradient;
    sfx.beginPath();
    sfx.arc(screenX, screenY, c.size * 4, 0, Math.PI * 2);
    sfx.fill();
    
    // Draw bright center point
    sfx.fillStyle = `rgba(${cr}, ${cg}, ${cb}, ${lifeAlpha})`;
    sfx.beginPath();
    sfx.arc(screenX, screenY, c.size * 0.8, 0, Math.PI * 2);
    sfx.fill();
  }
  
  // Draw stars with gravity effect around the latest idle mouse/touch point.
  const attractor = motionOff ? null : getReadyAttractor();
  const attractorX = attractor?.x ?? -999;
  const attractorY = attractor?.y ?? -999;
  const isAttractorIdle = Boolean(attractor);
  const attractorStoppedTime = attractor?.stoppedTime ?? 0;
  
  const cursorXNorm = attractorX / W;
  const cursorYNorm = attractorY / H;
  
  stars.forEach(s => {
    if (motionOff) {
      // Animation-lite mode: stars stay as a pure static background.
      s.x = s.baseX;
      s.y = s.baseY;
      s.vx = 0;
      s.vy = 0;
      s.distToTarget = 999;
    } else if (s.isStatic) {
      // Static stars don't move
      s.x = s.baseX;
      s.y = s.baseY;
    } else if (isAttractorIdle && attractorX > -999 && attractorStoppedTime > ATTRACTOR_READY_DELAY) {
      // VERY slow gravity pull - approximately 120-180 seconds to reach attractor
      const distX = cursorXNorm - s.baseX;
      const distY = cursorYNorm - s.baseY;
      const distance = Math.sqrt(distX * distX + distY * distY);
      s.distToTarget = distance;
      
      if (distance > 0.01) {
        const angle = Math.atan2(distY, distX);
        // Ultra-small acceleration for 3-4 minute approach (slower gravity)
        const accel = Math.max(0, 1 - distance * 0.7) * 0.000015;
        s.vx += Math.cos(angle) * accel;
        s.vy += Math.sin(angle) * accel;
      }
      
      s.vx *= 0.992; // Very high damping for super smooth motion
      s.vy *= 0.992;
      s.x += s.vx;
      s.y += s.vy;
    } else {
      // Return to base position when attractor moves or not idle
      const returnSpeed = 0.02; // Slower return for smoothness
      s.x += (s.baseX - s.x) * returnSpeed;
      s.y += (s.baseY - s.y) * returnSpeed;
      s.vx *= 0.88;
      s.vy *= 0.88;
      s.distToTarget = 999;
    }
  });
  
  drawCursorGlow(motionOff);
  
  // Draw individual stars with parallax and twinkling
  const scrollY = window.scrollY || 0;
  const maxScroll = Math.max(document.body.scrollHeight - window.innerHeight, 1);
  
  stars.forEach(s => {
    // Calculate parallax offset
    const parallaxOffset = motionOff ? 0 : (scrollY / maxScroll) * H * (1 - s.scrollDepth) * 0.08;
    
    let fl = 1;
    if (!motionOff && s.isTwinkling) {
      // Beautiful smooth twinkling with easing
      const twinklePeriod = 3000 + (s.ph % 2000);
      const twinkling = Math.sin(t * 0.001 * (2000 / twinklePeriod) + s.ph) * 0.35 + 0.65;
      fl = twinkling;
    } else if (!motionOff) {
      fl = Math.sin(t * s.sp * 1000 + s.ph) * 0.25 + 0.75;
    }
    
    const opacity = motionOff ? s.op : (s.isStatic ? s.op : s.op * fl);
    sfx.beginPath();
    sfx.arc(s.x * W, s.y * H + parallaxOffset, s.r, 0, Math.PI * 2);
    sfx.fillStyle = `rgba(200, 200, 255, ${opacity})`;
    sfx.fill();
  });
  
  // Draw beautiful nebulae with parallax and adaptive speed based on screen width
  const referenceWidth = 1440; // Base resolution for consistent timing across screens
  // Adaptive smoothness: smaller screens get smoother (slower) exit, larger screens faster
  const screenWidthFactor = Math.min(1, W / referenceWidth); // 0.24 on 350px, 1.0 on 1440px
  const smoothnessFactor = 0.4 + screenWidthFactor * 0.6; // 0.4-1.0 multiplier
  const nebulaWidth = Math.min(W, 1700);
  const nebulaOffsetX = (W - nebulaWidth) / 2;
  const nebulaHeight = Math.min(H, 1500);
  const nebulaLift = H > 1500 ? 100 : 0;
  const nebulaBlurScale = W > 1700 ? 1.55 : 1;
  const nebulaOpacityScale = W > 1700 ? 0.65 : 1;
  
  nebulae.forEach(neb => {
    // Update drift for organic micro-movement
    if (motionOff) {
      neb.drift = 0;
    } else {
      neb.drift += (Math.random() - 0.5) * neb.driftSpeed;
      neb.drift *= 0.98; // Damping
    }
    
    const scrollProgress = motionOff ? 0 : scrollY / maxScroll;
    const nebulaScrollFade = W > 1700 ? Math.max(0, 1 - scrollProgress * 4) : 1;
    
    // Adaptive movement speed based on screen width
    const baseMovement = scrollProgress * neb.dirX * 40 * smoothnessFactor;
    const parallaxNebX = nebulaOffsetX + neb.baseX * nebulaWidth + baseMovement * referenceWidth + neb.drift * nebulaWidth * 0.08;
    const parallaxNebY = neb.baseY * nebulaHeight - nebulaLift - (scrollProgress * nebulaHeight * neb.scrollSpeed * 0.35) + (scrollProgress * nebulaHeight * neb.dirY * 1.6);
    const nebulaRadius = neb.r * nebulaBlurScale;
    
    const nebGradient = sfx.createRadialGradient(
      parallaxNebX, parallaxNebY, 0,
      parallaxNebX, parallaxNebY, nebulaRadius
    );
    
    neb.colors.forEach(c => {
      const nebulaColor = c.color.replace(/rgba\(([^,]+),([^,]+),([^,]+),([^)]+)\)/, (_, r, g, b, a) => `rgba(${r},${g},${b},${parseFloat(a) * nebulaOpacityScale * nebulaScrollFade})`);
      nebGradient.addColorStop(c.stop, nebulaColor);
    });
    
    sfx.fillStyle = nebGradient;
    sfx.beginPath();
    sfx.arc(parallaxNebX, parallaxNebY, nebulaRadius, 0, Math.PI * 2);
    sfx.fill();
  });
  
  if (!motionOff) scheduleStarfieldFrame();
}
scheduleStarfieldFrame();

/* ─────────────────────────────────────────────
   CURSOR
───────────────────────────────────────────── */
cRing = cRing || document.getElementById('curRing');
cDot  = cDot  || document.getElementById('curDot');

function isCustomCursorEnabled() {
  return hasFinePointer && !isPartialMotionDisabled() && !customCursorSuppressed;
}

function shouldSuppressCustomCursor(target) {
  return Boolean(target?.closest?.(CUSTOM_CURSOR_SUPPRESS_SELECTOR));
}

function syncCustomCursorSuppression(target) {
  const shouldSuppress = shouldSuppressCustomCursor(target);
  if (customCursorSuppressed === shouldSuppress) return;

  customCursorSuppressed = shouldSuppress;
  attractorSuppressed = shouldSuppress;
  if (shouldSuppress) {
    stopCustomCursorLoop();
  } else {
    syncCustomCursorState();
  }
}

function setCursorElementsVisible(visible) {
  if (!cRing || !cDot) return;
  cRing.style.display = visible ? '' : 'none';
  cDot.style.display = visible ? '' : 'none';
  cRing.style.opacity = visible ? '' : '0';
  cDot.style.opacity = visible ? '' : '0';
}

function moveCursorTo(x, y, shouldSnap = false) {
  if (!isCustomCursorEnabled()) return;
  mx = x;
  my = y;
  if (shouldSnap) {
    rx = x;
    ry = y;
  }
  startCustomCursorLoop();
}

function startCustomCursorLoop() {
  if (!cRing || !cDot || cursorLoopRunning || !isCustomCursorEnabled()) return;
  cursorLoopRunning = true;
  setCursorElementsVisible(true);
  cursorFrameId = requestAnimationFrame(loopCursor);
}

function stopCustomCursorLoop() {
  cursorLoopRunning = false;
  if (cursorFrameId) {
    cancelAnimationFrame(cursorFrameId);
    cursorFrameId = 0;
  }
  setCursorElementsVisible(false);
}

function syncCustomCursorState() {
  if (isCustomCursorEnabled()) {
    setCursorElementsVisible(true);
    startCustomCursorLoop();
  } else {
    stopCustomCursorLoop();
  }
}

document.addEventListener('mousemove', e => {
  syncCustomCursorSuppression(e.target);
  if (!activateMouseInput(e) || !isCustomCursorEnabled()) return;
  moveCursorTo(e.clientX, e.clientY);
}, inputCaptureOptions);
document.addEventListener('mousedown', e => {
  syncCustomCursorSuppression(e.target);
  if (!activateMouseInput(e) || !isCustomCursorEnabled()) return;
  moveCursorTo(e.clientX, e.clientY);
}, inputCaptureOptions);
document.addEventListener('mouseover', e => {
  syncCustomCursorSuppression(e.target);
  if (!activateMouseInput(e) || !isCustomCursorEnabled()) return;
  moveCursorTo(e.clientX, e.clientY);
}, inputCaptureOptions);
document.addEventListener('pointermove', e => {
  syncCustomCursorSuppression(e.target);
  if (e.pointerType !== 'mouse' || !activateMouseInput(e) || !isCustomCursorEnabled()) return;
  moveCursorTo(e.clientX, e.clientY);
}, inputCaptureOptions);
document.addEventListener('pointerdown', e => {
  syncCustomCursorSuppression(e.target);
  if (e.pointerType !== 'mouse' || !activateMouseInput(e) || !isCustomCursorEnabled()) return;
  moveCursorTo(e.clientX, e.clientY);
}, inputCaptureOptions);

document.addEventListener('focusin', e => {
  syncCustomCursorSuppression(e.target);
}, true);

document.addEventListener('focusout', () => {
  setTimeout(() => syncCustomCursorSuppression(document.activeElement), 0);
}, true);

// Lag ring — runs only when heavy animations are enabled.
function loopCursor() {
  if (!cursorLoopRunning || !isCustomCursorEnabled() || !cRing || !cDot) {
    stopCustomCursorLoop();
    return;
  }

  rx += (mx - rx) * 0.14;
  ry += (my - ry) * 0.14;
  cDot.style.left = `${mx}px`;
  cDot.style.top = `${my}px`;
  cRing.style.left = `${rx}px`;
  cRing.style.top = `${ry}px`;
  cRing.style.width = '30px';
  cRing.style.height = '30px';
  cursorFrameId = requestAnimationFrame(loopCursor);
}

syncCustomCursorState();

document.addEventListener('mousedown', e => {
  if (!isCustomCursorEnabled() || !cRing || isLikelySyntheticMouseEvent(e)) return;
  cRing.style.transform = 'translate(-50%,-50%) scale(.82)';
}, inputCaptureOptions);
document.addEventListener('mouseup', e => {
  if (!isCustomCursorEnabled() || !cRing || isLikelySyntheticMouseEvent(e)) return;
  cRing.style.transform = 'translate(-50%,-50%) scale(1)';
}, inputCaptureOptions);

/* ─────────────────────────────────────────────
   SCROLL PROGRESS
───────────────────────────────────────────── */
const pb = document.getElementById('pb');
let scrollProgressRaf = null;

function updateScrollProgress() {
  if (!pb) return;
  const pct = (window.scrollY / (document.body.scrollHeight - window.innerHeight)) * 100;
  pb.style.width = pct + '%';
}

function requestScrollProgressUpdate() {
  if (scrollProgressRaf) return;
  scrollProgressRaf = requestAnimationFrame(() => {
    scrollProgressRaf = null;
    updateScrollProgress();
  });
}

window.addEventListener('scroll', requestScrollProgressUpdate, { passive:true });
window.addEventListener('resize', requestScrollProgressUpdate, { passive:true });
updateScrollProgress();

/* ─────────────────────────────────────────────
   CASE REELS
───────────────────────────────────────────── */
const works = document.querySelectorAll('.work');
const workVisuals = Array.from(works, work => work.querySelector('.work-visual')).filter(Boolean);
const caseReelControllers = new WeakMap();
const CASE_REEL_SCENES = [
  { key:'intent', index:'01' },
  { key:'structure', index:'02' },
  { key:'aim', index:'03' }
];

function getCaseReelScenes(work) {
  if (!work?.dataset) return [];
  return CASE_REEL_SCENES
    .map(scene => ({
      ...scene,
      label: TOOLS[scene.key]?.label || scene.key,
      text: (work.dataset[scene.key] || '').trim()
    }))
    .filter(scene => scene.text);
}

function setCaseReelStrip(strip, scene) {
  if (!strip) return;
  strip.replaceChildren();
  const words = scene.text.split(/\s+/).filter(Boolean).slice(0, 14);
  const tokens = [scene.label, ...words, scene.label, ...words.slice(0, 8)];
  tokens.forEach(token => {
    const span = document.createElement('span');
    span.textContent = token;
    strip.appendChild(span);
  });
}

function setupCaseReel(work, i) {
  const vis = work.querySelector('.work-visual');
  const inn = work.querySelector('.wv-inner');
  const ov = work.querySelector('.wv-overlay');
  if (!vis || !inn || !ov) return;

  const scenes = getCaseReelScenes(work);
  if (!scenes.length) return;

  const trigger = document.createElement('button');
  trigger.className = 'case-reel-trigger';
  trigger.type = 'button';
  trigger.setAttribute('aria-label', 'Show goal, structure, and business impact');
  trigger.innerHTML = `
    <span class="case-reel-trigger-pulse" aria-hidden="true"></span>
    <span class="case-reel-orbit" aria-hidden="true">
      <svg viewBox="0 0 16 16" fill="currentColor">
        <path d="M5.2 3.2 12 8l-6.8 4.8Z"/>
      </svg>
    </span>
    <span class="case-reel-trigger-text">View the essence</span>
  `;
  // Case reel now lives in the narrator media bay, not on the case visual.

  ov.innerHTML = `
    <div class="case-reel-shell">
      <div class="case-reel-top">
        <div class="case-reel-kicker">case reel</div>
        <button class="case-reel-close" type="button" aria-label="Close">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round">
            <path d="M6 6l12 12M18 6 6 18"/>
          </svg>
        </button>
      </div>
      <div class="case-reel-stage">
        <div class="case-reel-scene-head">
          <div class="case-reel-scene-label"></div>
          <div class="case-reel-count"></div>
        </div>
        <div class="case-reel-text"></div>
        <div class="case-reel-strip" aria-hidden="true"></div>
      </div>
      <div class="case-reel-nav"></div>
    </div>
  `;

  const closeBtn = ov.querySelector('.case-reel-close');
  const labelEl = ov.querySelector('.case-reel-scene-label');
  const countEl = ov.querySelector('.case-reel-count');
  const textEl = ov.querySelector('.case-reel-text');
  const stripEl = ov.querySelector('.case-reel-strip');
  const navEl = ov.querySelector('.case-reel-nav');
  let activeScene = 0;
  let typeTimer = 0;
  let sceneTimer = 0;

  const stepBtns = scenes.map((scene, sceneIndex) => {
    const btn = document.createElement('button');
    btn.className = 'case-reel-step';
    btn.type = 'button';
    btn.textContent = scene.label;
    btn.addEventListener('click', () => showCaseReelScene(sceneIndex, true));
    navEl.appendChild(btn);
    return btn;
  });

  function clearCaseReelTimers() {
    clearTimeout(typeTimer);
    clearTimeout(sceneTimer);
  }

  function typeCaseReelText(text) {
    clearTimeout(typeTimer);
    textEl.textContent = '';
    const chars = Array.from(text);
    const step = Math.max(1, Math.ceil(chars.length / 165));
    let cursor = 0;

    function tick() {
      cursor = Math.min(chars.length, cursor + step);
      textEl.textContent = chars.slice(0, cursor).join('');
      if (cursor < chars.length) {
        typeTimer = setTimeout(tick, 17);
      }
    }

    tick();
  }

  function showCaseReelScene(sceneIndex, manual = false) {
    const scene = scenes[sceneIndex];
    if (!scene) return;

    activeScene = sceneIndex;
    const duration = Math.min(9800, Math.max(5200, 1700 + Array.from(scene.text).length * 30));
    ov.style.setProperty('--scene-ms', `${duration}ms`);
    labelEl.textContent = scene.label;
    countEl.textContent = scene.index;
    setCaseReelStrip(stripEl, scene);
    typeCaseReelText(scene.text);

    stepBtns.forEach(btn => btn.classList.remove('is-active'));
    void navEl.offsetWidth;
    stepBtns.forEach((btn, idx) => {
      btn.classList.toggle('is-active', idx === sceneIndex);
      btn.setAttribute('aria-pressed', idx === sceneIndex ? 'true' : 'false');
    });

    const aspectKey = `${scene.key}:${i}`;
    if (!watchedCaseAspects.has(aspectKey)) {
      watchedCaseAspects.add(aspectKey);
      trackEvent(`${scene.key} case ${getWorkTitle(work)} watched`);
    }

    clearTimeout(sceneTimer);
    sceneTimer = setTimeout(() => {
      showCaseReelScene((activeScene + 1) % scenes.length);
    }, duration);

    if (manual) playUI('switch');
  }

  function openCaseReel() {
    workVisuals.forEach(otherVis => {
      if (otherVis !== vis) {
        const otherController = caseReelControllers.get(otherVis);
        otherController?.close();
      }
    });

    vis.classList.add('reel-open');
    ov.classList.add('show');
    trigger.setAttribute('aria-expanded', 'true');
    showCaseReelScene(0);
    playUI('switch');
    trackEvent(`case reel opened: ${getWorkTitle(work)}`);
  }

  function closeCaseReel() {
    clearCaseReelTimers();
    vis.classList.remove('reel-open');
    ov.classList.remove('show');
    trigger.setAttribute('aria-expanded', 'false');
  }

  trigger.setAttribute('aria-expanded', 'false');
  trigger.addEventListener('click', e => {
    e.preventDefault();
    e.stopPropagation();
    if (ov.classList.contains('show')) {
      closeCaseReel();
    } else {
      openCaseReel();
    }
  });

  closeBtn.addEventListener('click', e => {
    e.preventDefault();
    e.stopPropagation();
    closeCaseReel();
    playUI('switch');
  });

  vis.addEventListener('mouseenter', e => {
    if (!isRealMouseEvent(e)) return;
    playUI('hover');
  });

  vis.addEventListener('mousemove', e => {
    if (!isRealMouseEvent(e)) return;
    if (isPartialMotionDisabled() || ov.classList.contains('show')) return;

    const r = vis.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width - 0.5;
    const y = (e.clientY - r.top) / r.height - 0.5;
    const tx = y * -8;
    const ty = x * 8;
    vis.style.transform = `perspective(820px) rotateX(${tx}deg) rotateY(${ty}deg) translateZ(10px)`;
    inn.style.transform = `translateX(${x * -7}px) translateY(${y * -7}px)`;
  });

  vis.addEventListener('touchstart', () => {
    playUI('hover');
  }, { passive:true });

  vis.addEventListener('mouseleave', e => {
    if (!isRealMouseEvent(e)) return;
    if (ov.classList.contains('show')) return;
    vis.style.transform = 'perspective(820px) rotateX(0) rotateY(0) translateZ(0)';
    inn.style.transform = 'none';
  });

  caseReelControllers.set(vis, {
    close: closeCaseReel,
    isOpen: () => ov.classList.contains('show')
  });
}

works.forEach(setupCaseReel);

function clearWorkVisualStates() {
  works.forEach(work => {
    const vis = work.querySelector('.work-visual');
    const inn = work.querySelector('.wv-inner');
    const ov = work.querySelector('.wv-overlay');
    if (!vis || !inn || !ov) return;
    vis.style.transform = 'perspective(820px) rotateX(0) rotateY(0) translateZ(0)';
    inn.style.transform = 'none';
    caseReelControllers.get(vis)?.close();
    ov.classList.remove('show');
  });
}

document.addEventListener('touchstart', e => {
  if (e.target?.closest?.('.work-visual')) return;
  clearWorkVisualStates();
}, inputCaptureOptions);

document.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  clearWorkVisualStates();
});

/* ─────────────────────────────────────────────
   PARALLAX SCROLL REVEAL - REPEATING FOR WORKS
───────────────────────────────────────────── */
if ('IntersectionObserver' in window) {
  const workObs = new IntersectionObserver(entries => {
    entries.forEach(e => {
      if (e.isIntersecting) {
        e.target.classList.add('visible');
      } else {
        e.target.classList.remove('visible');
      }
    });
  }, { threshold: 0.1 });
  works.forEach(w => workObs.observe(w));
} else {
  works.forEach(w => w.classList.add('visible'));
}

/* ─────────────────────────────────────────────
   PARALLAX REVEAL FOR MOTION (EARLY)
───────────────────────────────────────────── */
const motionCardsForReveal = document.querySelectorAll('.motion-card');
if ('IntersectionObserver' in window) {
  const motionParallaxObs = new IntersectionObserver(entries => {
    entries.forEach(e => {
      if (e.isIntersecting) {
        e.target.classList.add('parallax-visible');
      } else {
        e.target.classList.remove('parallax-visible');
      }
    });
  }, { threshold: 0.0, rootMargin: '10px 0px' });

  // Observe motion cards with early trigger
  motionCardsForReveal.forEach(card => motionParallaxObs.observe(card));
} else {
  motionCardsForReveal.forEach(card => card.classList.add('parallax-visible'));
}

/* ─────────────────────────────────────────────
   PARALLAX REVEAL FOR PRINTED & SOCIAL
───────────────────────────────────────────── */
const printedItemsForReveal = document.querySelectorAll('.printed-item');
const socialPostsForReveal = document.querySelectorAll('.social-post');
if ('IntersectionObserver' in window) {
  const parallaxElementsObs = new IntersectionObserver(entries => {
    entries.forEach(e => {
      if (e.isIntersecting) {
        e.target.classList.add('parallax-visible');
      } else {
        e.target.classList.remove('parallax-visible');
      }
    });
  }, { threshold: 0.0 });

  // Observe printed items
  printedItemsForReveal.forEach(item => parallaxElementsObs.observe(item));
  // Observe social posts
  socialPostsForReveal.forEach(post => parallaxElementsObs.observe(post));
} else {
  printedItemsForReveal.forEach(item => item.classList.add('parallax-visible'));
  socialPostsForReveal.forEach(post => post.classList.add('parallax-visible'));
}

/* ─────────────────────────────────────────────
   MEDIA PRELOADERS
───────────────────────────────────────────── */
const MEDIA_LOADBOX_SELECTORS = [
  '.wv-media',
  '.motion-card-media',
  '.printed-visual',
  '.post-visual',
  '.carousel-slide',
  '.expandable-media-container'
];

function getMediaLoadbox(media) {
  const box = media.closest(MEDIA_LOADBOX_SELECTORS.join(','));
  if (box) return box;

  const narratorText = document.getElementById('narText');
  if (narratorText?.contains(media) && media.parentElement) {
    const parent = media.parentElement;
    if (parent.tagName === 'SPAN' && parent.parentElement === narratorText) {
      syncNarratorInlineMediaSpacing(media, parent);
      parent.classList.add('nar-inline-media-loadbox', 'nar-generated-media-loadbox');
    }
    return parent;
  }

  return null;
}

function syncNarratorInlineMediaSpacing(media, box) {
  if (!media || !box || box.dataset.narSpacingSynced === '1') return;
  const style = window.getComputedStyle?.(media);
  box.style.marginTop = media.style.marginTop || style?.marginTop || '0px';
  box.style.marginRight = media.style.marginRight || style?.marginRight || '0px';
  box.style.marginBottom = media.style.marginBottom || style?.marginBottom || '0px';
  box.style.marginLeft = media.style.marginLeft || style?.marginLeft || '0px';
  box.dataset.narSpacingSynced = '1';
}

function isMediaReady(media) {
  if (media.tagName === 'IMG') return media.complete && media.naturalWidth > 0;
  if (media.tagName === 'VIDEO') return media.readyState >= 2;
  return true;
}

function updateMediaLoadbox(media, state) {
  const box = getMediaLoadbox(media);
  if (!box) return;

  box.classList.add('media-loadbox');
  box.classList.toggle('media-loading', state === 'loading');
  box.classList.toggle('media-error', state === 'error');
}

function syncMediaLoadbox(media) {
  const box = getMediaLoadbox(media);
  if (!box) return;

  const mediaItems = Array.from(box.querySelectorAll('img, video'));

  if (mediaItems.some(item => item.dataset.preloaderError === '1')) {
    updateMediaLoadbox(media, 'error');
    return;
  }

  if (mediaItems.length && mediaItems.every(isMediaReady)) {
    updateMediaLoadbox(media, 'ready');
  } else {
    updateMediaLoadbox(media, 'loading');
  }
}

function prepareMediaPreloader(media) {
  if (!media || media.dataset.preloaderReady === '1') return;
  media.dataset.preloaderReady = '1';

  const hasDeferredSource = Boolean(media.dataset.bgSrc || media.querySelector?.('source[data-bg-src]'));
  const hasImmediateSource = Boolean(media.currentSrc || media.src || media.querySelector?.('source[src]'));

  if (!isMediaReady(media) || hasDeferredSource || !hasImmediateSource) {
    updateMediaLoadbox(media, 'loading');
  }

  const markReady = () => {
    media.dataset.preloaderError = '0';
    syncMediaLoadbox(media);
  };
  const markError = () => {
    media.dataset.preloaderError = '1';
    updateMediaLoadbox(media, 'error');
  };

  if (media.tagName === 'IMG') {
    media.addEventListener('load', markReady, { once: true });
    media.addEventListener('error', markError, { once: true });
  } else if (media.tagName === 'VIDEO') {
    media.addEventListener('loadeddata', markReady, { once: true });
    media.addEventListener('canplay', markReady, { once: true });
    media.addEventListener('error', markError, { once: true });
  }

  if (isMediaReady(media) && hasImmediateSource && !hasDeferredSource) {
    markReady();
  }
}

function initMediaPreloaders(root = document) {
  root.querySelectorAll?.('img, video').forEach(prepareMediaPreloader);
}

initMediaPreloaders();

/* ─────────────────────────────────────────────
   VIEWPORT VIDEO PLAYBACK
───────────────────────────────────────────── */
const VIEWPORT_VIDEO_EXCLUDE_SELECTOR = '#narrator';
const VIEWPORT_VIDEO_SELECTOR = 'video[data-viewport-video]';
const viewportManagedVideos = new Set();
const viewportVideoVisibility = new WeakMap();
let viewportVideoLoadObserver = null;
let viewportVideoObserver = null;
let viewportVideoFallbackRaf = null;

function isViewportVideoExcluded(video) {
  return Boolean(video.closest?.(VIEWPORT_VIDEO_EXCLUDE_SELECTOR));
}

function isNarratorModalOpen() {
  return Boolean(nar?.classList.contains('show') || document.body.classList.contains('story-modal-open'));
}

function isVideoInViewport(video) {
  if (!video.isConnected || isViewportVideoExcluded(video) || isNarratorModalOpen()) return false;
  const rect = video.getBoundingClientRect();
  return rect.width > 0
    && rect.height > 0
    && rect.bottom > 0
    && rect.right > 0
    && rect.top < window.innerHeight
    && rect.left < window.innerWidth;
}

function hydrateDeferredVideo(video) {
  let shouldLoad = false;

  if (video.dataset.bgSrc) {
    video.setAttribute('src', video.dataset.bgSrc);
    video.removeAttribute('data-bg-src');
    shouldLoad = true;
  }

  video.querySelectorAll?.('source[data-bg-src]').forEach(source => {
    source.setAttribute('src', source.dataset.bgSrc);
    source.removeAttribute('data-bg-src');
    shouldLoad = true;
  });

  if (shouldLoad) {
    updateMediaLoadbox(video, 'loading');
    video.load();
  }
}

function ensureViewportVideoLoadObserver() {
  if (viewportVideoLoadObserver || !('IntersectionObserver' in window)) {
    return viewportVideoLoadObserver;
  }

  viewportVideoLoadObserver = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      hydrateDeferredVideo(entry.target);
      viewportVideoLoadObserver.unobserve(entry.target);
    });
  }, { rootMargin: '120px 0px', threshold: 0 });

  return viewportVideoLoadObserver;
}

function syncViewportVideo(video, visible = isVideoInViewport(video)) {
  if (!video || !video.matches?.(VIEWPORT_VIDEO_SELECTOR)) return;

  if (!video.isConnected || isViewportVideoExcluded(video) || isNarratorModalOpen()) {
    video.pause();
    return;
  }

  viewportVideoVisibility.set(video, visible);

  if (!visible || document.hidden) {
    video.pause();
    return;
  }

  hydrateDeferredVideo(video);
  video.play().catch(() => {});
}

function ensureViewportVideoObserver() {
  if (viewportVideoObserver || !('IntersectionObserver' in window)) {
    return viewportVideoObserver;
  }

  viewportVideoObserver = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      syncViewportVideo(entry.target, entry.isIntersecting && entry.intersectionRatio > 0);
    });
  }, { threshold: 0.01 });

  return viewportVideoObserver;
}

function registerViewportVideo(video) {
  if (!video || !video.matches?.(VIEWPORT_VIDEO_SELECTOR) || viewportManagedVideos.has(video)) return;
  if (isViewportVideoExcluded(video)) return;

  viewportManagedVideos.add(video);
  video.pause();

  const loadObserver = ensureViewportVideoLoadObserver();
  if (loadObserver) {
    loadObserver.observe(video);
  }

  const observer = ensureViewportVideoObserver();
  if (observer) {
    observer.observe(video);
  } else {
    syncViewportVideo(video);
  }
}

function initViewportVideoPlayback(root = document) {
  if (root.matches?.(VIEWPORT_VIDEO_SELECTOR)) {
    registerViewportVideo(root);
  }
  root.querySelectorAll?.(VIEWPORT_VIDEO_SELECTOR).forEach(registerViewportVideo);
}

function syncAllViewportVideos() {
  viewportManagedVideos.forEach(video => {
    if (!video.isConnected) {
      viewportVideoLoadObserver?.unobserve(video);
      viewportVideoObserver?.unobserve(video);
      viewportManagedVideos.delete(video);
      return;
    }
    syncViewportVideo(video, viewportVideoVisibility.get(video) ?? isVideoInViewport(video));
  });
}

function requestViewportVideoFallbackSync() {
  if (viewportVideoObserver || viewportVideoFallbackRaf) return;
  viewportVideoFallbackRaf = requestAnimationFrame(() => {
    viewportVideoFallbackRaf = null;
    syncAllViewportVideos();
  });
}

initViewportVideoPlayback();

if (!viewportVideoObserver) {
  window.addEventListener('scroll', requestViewportVideoFallbackSync, { passive: true });
  window.addEventListener('resize', requestViewportVideoFallbackSync, { passive: true });
}

document.addEventListener('visibilitychange', syncAllViewportVideos);

/* ─────────────────────────────────────────────
   NARRATOR
───────────────────────────────────────────── */
const nar        = document.getElementById('narrator');
const narText    = document.getElementById('narText');
const narFrom    = document.getElementById('narFrom');
const narClose   = document.getElementById('narClose');
const storyProgress = document.getElementById('storyProgress');
const storyPrev = document.getElementById('storyPrev');
const storyNext = document.getElementById('storyNext');
const storyCounter = document.getElementById('storyCounter');
const storyScrollbar = document.getElementById('storyScrollbar');
const storyScrollbarThumb = document.getElementById('storyScrollbarThumb');
let narHidden = false;
let activeTimers = [];
let activeIntervals = [];
let currentNarWork = null;
let narratorStoryScenes = [];
let narratorStoryIndex = 0;
let narratorLastTrigger = null;
let narratorStoryDone = false;
let storyScrollSyncRaf = null;
let storyScrollbarDragging = false;
let storyActiveProgress = 1;
let narAutoScroll = true;
let narLastScrollTop = 0;
let narUserScrollIntent = false;
let narUserScrollIntentTimer = null;
let narProgrammaticScroll = false;
let narProgrammaticScrollTimer = null;
let narScrollRaf = null;
let narratorPageScrollY = 0;
let narratorInitialStageMediaHtml = '';
let narratorSuppressCaseReel = false;
let storyTouchLastY = null;
let narVirtualScrollTop = 0;
let narVirtualMaxScroll = 0;
let narStoryEstimatedMaxScroll = 0;
let narratorStoryRevealedCount = 0;
let storyCaseReelTimer = 0;
let storyCaseReelStartedAt = 0;
let storyCaseReelRemaining = 0;
let storyCaseReelActiveRoot = null;
let storyCaseReelActiveScenes = null;
let storyCaseReelActiveIndex = 0;

function scheduleNarratorFrame(callback) {
  const schedule = window.requestAnimationFrame || (cb => window.setTimeout(cb, 16));
  return schedule(callback);
}

function cancelNarratorFrame(id) {
  if (window.cancelAnimationFrame) {
    window.cancelAnimationFrame(id);
  } else {
    clearTimeout(id);
  }
}

function getNarratorScrollContent() {
  return narText?.querySelector('.story-scroll-layout:not(.story-measure-layout)') || null;
}

function isNarratorMobileStoryLayout() {
  return window.matchMedia?.('(max-width:950px)')?.matches;
}

function getNarratorFeedViewport(layout = getNarratorScrollContent()) {
  return layout?.querySelector('.story-feed') || null;
}

function getNarratorFeedTrack(layout = getNarratorScrollContent()) {
  return layout?.querySelector('.story-feed-track') || getNarratorFeedViewport(layout);
}

function getNarratorScrollViewportHeight() {
  return getNarratorFeedViewport()?.clientHeight || narText?.clientHeight || 0;
}

function measureNarratorLayoutMaxScroll(layout) {
  if (!narText || !layout) return 0;
  const feed = getNarratorFeedViewport(layout);
  const track = getNarratorFeedTrack(layout);
  if (!feed || !track) return 0;
  return Math.max(0, track.scrollHeight - feed.clientHeight);
}

function measureNarratorMaxScroll() {
  const content = getNarratorScrollContent();
  return measureNarratorLayoutMaxScroll(content);
}

function getNarratorTrackMaxScroll() {
  return Math.max(narVirtualMaxScroll, narStoryEstimatedMaxScroll);
}

function isNarratorNearBottom(threshold = 12) {
  narVirtualMaxScroll = measureNarratorMaxScroll();
  return narVirtualMaxScroll - narVirtualScrollTop <= threshold;
}

function markNarratorUserScrollIntent() {
  narUserScrollIntent = true;
  clearTimeout(narUserScrollIntentTimer);
  narUserScrollIntentTimer = setTimeout(() => {
    narUserScrollIntent = false;
  }, 700);
}

function guardNarratorProgrammaticScroll() {
  narProgrammaticScroll = true;
  clearTimeout(narProgrammaticScrollTimer);
  narProgrammaticScrollTimer = setTimeout(() => {
    narProgrammaticScroll = false;
  }, 120);
}

function resetNarratorAutoScroll() {
  narAutoScroll = true;
  narUserScrollIntent = false;
  narProgrammaticScroll = false;
  narVirtualScrollTop = 0;
  narVirtualMaxScroll = measureNarratorMaxScroll();
  clearTimeout(narUserScrollIntentTimer);
  clearTimeout(narProgrammaticScrollTimer);
  if (narScrollRaf) {
    cancelNarratorFrame(narScrollRaf);
    narScrollRaf = null;
  }
  narLastScrollTop = 0;
  applyNarratorVirtualScroll();
  requestStoryScrollSync();
}

function applyNarratorVirtualScroll() {
  const content = getNarratorScrollContent();
  if (!content) return;
  const roundedTop = Math.round(narVirtualScrollTop);
  const visual = content.querySelector('.story-visual');
  const feedTrack = getNarratorFeedTrack(content);
  content.style.transform = '';
  if (feedTrack) feedTrack.style.transform = `translate3d(0, ${-roundedTop}px, 0)`;
  visual?.style.setProperty('--story-visual-y', '0px');
}

function syncNarratorVirtualScrollState() {
  const wasNearBottom = narVirtualMaxScroll - narVirtualScrollTop <= 12;
  narVirtualMaxScroll = measureNarratorMaxScroll();
  if (narAutoScroll && wasNearBottom) {
    narVirtualScrollTop = narVirtualMaxScroll;
  } else {
    narVirtualScrollTop = Math.max(0, Math.min(narVirtualScrollTop, narVirtualMaxScroll));
  }
  applyNarratorVirtualScroll();
  updateStoryScrollbar();
}

function setNarratorVirtualScroll(nextTop, { user = false } = {}) {
  narVirtualMaxScroll = measureNarratorMaxScroll();
  const previousTop = narVirtualScrollTop;
  narVirtualScrollTop = Math.max(0, Math.min(nextTop, narVirtualMaxScroll));

  if (user) {
    markNarratorUserScrollIntent();
    if (narVirtualScrollTop < previousTop - 2 && !isNarratorNearBottom(2)) {
      narAutoScroll = false;
    }
    if (isNarratorNearBottom()) narAutoScroll = true;
  }

  narLastScrollTop = narVirtualScrollTop;
  applyNarratorVirtualScroll();
  requestNarratorVideoSync();
  requestStoryScrollSync();
}

function applyNarratorScrollToBottom() {
  if (!narText || !narAutoScroll) return;
  guardNarratorProgrammaticScroll();
  narVirtualMaxScroll = measureNarratorMaxScroll();
  narVirtualScrollTop = narVirtualMaxScroll;
  narLastScrollTop = narVirtualScrollTop;
  applyNarratorVirtualScroll();
  requestNarratorVideoSync();
  requestStoryScrollSync();
}

function scrollNarratorToBottom() {
  if (!narText || !narAutoScroll) return;
  if (!narScrollRaf) {
    narScrollRaf = scheduleNarratorFrame(() => {
      narScrollRaf = null;
      applyNarratorScrollToBottom();
    });
  }
}

if (narText) {
  narText.addEventListener('wheel', e => {
    markNarratorUserScrollIntent();
    if (e.deltaY < 0 && !isNarratorNearBottom(2)) narAutoScroll = false;
  }, { passive: true });
  narText.addEventListener('touchmove', markNarratorUserScrollIntent, { passive: true });
  narText.addEventListener('pointerdown', (e) => {
    const rect = narText.getBoundingClientRect();
    if (e.clientX >= rect.right - 16) markNarratorUserScrollIntent();
  }, { passive: true });
  narText.addEventListener('scroll', () => {
    requestNarratorVideoSync();
    requestStoryScrollSync();
  }, { passive: true });
}

nar?.addEventListener('wheel', e => {
  if (!nar.classList.contains('show') || !narText) return;
  if (e.cancelable) e.preventDefault();

  const delta = e.deltaY || 0;
  if (!delta) return;

  markNarratorUserScrollIntent();
  if (delta < 0 && !isNarratorNearBottom(2)) narAutoScroll = false;
  setNarratorVirtualScroll(narVirtualScrollTop + delta, { user:true });
  if (isNarratorNearBottom()) narAutoScroll = true;
}, { passive:false });

nar?.addEventListener('touchstart', e => {
  if (!nar.classList.contains('show')) return;
  storyTouchLastY = e.touches?.[0]?.clientY ?? null;
}, { passive:true });

nar?.addEventListener('touchmove', e => {
  if (!nar.classList.contains('show') || !narText) return;
  const touchY = e.touches?.[0]?.clientY;
  if (touchY == null) return;
  if (e.cancelable) e.preventDefault();

  if (storyTouchLastY == null) {
    storyTouchLastY = touchY;
    return;
  }

  const delta = storyTouchLastY - touchY;
  storyTouchLastY = touchY;
  if (!delta) return;

  markNarratorUserScrollIntent();
  if (delta < 0 && !isNarratorNearBottom(2)) narAutoScroll = false;
  setNarratorVirtualScroll(narVirtualScrollTop + delta, { user:true });
  if (isNarratorNearBottom()) narAutoScroll = true;
}, { passive:false });

nar?.addEventListener('touchend', () => {
  storyTouchLastY = null;
  if (isNarratorNearBottom()) narAutoScroll = true;
}, { passive:true });

nar?.addEventListener('touchcancel', () => {
  storyTouchLastY = null;
}, { passive:true });

function setNarratorScrollFromScrollbar(clientY) {
  if (!narText || !storyScrollbarThumb) return;
  const track = storyScrollbar?.querySelector('.story-scrollbar-track');
  if (!track) return;

  narVirtualMaxScroll = measureNarratorMaxScroll();
  const rect = track.getBoundingClientRect();
  const thumbHeight = storyScrollbarThumb.offsetHeight || 34;
  const maxThumbY = Math.max(1, rect.height - thumbHeight);
  const y = Math.max(0, Math.min(maxThumbY, clientY - rect.top - thumbHeight / 2));

  narAutoScroll = false;
  narUserScrollIntent = true;
  setNarratorVirtualScroll(narVirtualMaxScroll * (y / maxThumbY), { user:true });
}

storyScrollbar?.addEventListener('pointerdown', e => {
  e.preventDefault();
  storyScrollbarDragging = true;
  storyScrollbar.setPointerCapture?.(e.pointerId);
  setNarratorScrollFromScrollbar(e.clientY);
}, { passive:false });

storyScrollbar?.addEventListener('pointermove', e => {
  if (!storyScrollbarDragging) return;
  e.preventDefault();
  setNarratorScrollFromScrollbar(e.clientY);
}, { passive:false });

storyScrollbar?.addEventListener('pointerup', e => {
  storyScrollbarDragging = false;
  storyScrollbar.releasePointerCapture?.(e.pointerId);
  if (isNarratorNearBottom()) narAutoScroll = true;
}, { passive:true });

storyScrollbar?.addEventListener('pointercancel', () => {
  storyScrollbarDragging = false;
}, { passive:true });

function clearAllTimers() {
  activeTimers.forEach(id => clearTimeout(id));
  activeIntervals.forEach(id => clearInterval(id));
  activeTimers = [];
  activeIntervals = [];
}

function releaseLoadedMedia(root) {
  if (!root) return;

  clearStoryStageCarousels(root);

  root.querySelectorAll('video, audio').forEach(media => {
    media.pause?.();
    media.removeAttribute('src');
    media.querySelectorAll('source').forEach(source => {
      source.removeAttribute('src');
      source.removeAttribute('srcset');
    });
    media.load?.();
  });

  root.querySelectorAll('img').forEach(img => {
    img.removeAttribute('src');
    img.removeAttribute('srcset');
    img.removeAttribute('sizes');
  });

  root.querySelectorAll('picture source').forEach(source => {
    source.removeAttribute('src');
    source.removeAttribute('srcset');
    source.removeAttribute('sizes');
  });
}

function clearNarratorContent() {
  if (!narText) return;
  clearStoryCaseReelTimers();
  pauseNarratorVideos();
  releaseLoadedMedia(narText);
  guardNarratorProgrammaticScroll();
  narText.innerHTML = '';
  narVirtualScrollTop = 0;
  narVirtualMaxScroll = 0;
  narStoryEstimatedMaxScroll = 0;
  narratorStoryRevealedCount = 0;
  narLastScrollTop = 0;
  updateStoryScrollbar();
}

function pauseNarratorVideos(exceptVideo = null) {
  if (!narText) return;
  narText.querySelectorAll('video[data-narrator-video-managed="1"]').forEach(video => {
    if (video !== exceptVideo) video.pause?.();
  });
}

function getNarratorVideoVisibleRatio(video) {
  if (!narText || !video?.isConnected) return 0;
  const rootRect = narText.getBoundingClientRect();
  const rect = video.getBoundingClientRect();
  if (!rect.width || !rect.height) return 0;

  const visibleWidth = Math.max(0, Math.min(rect.right, rootRect.right) - Math.max(rect.left, rootRect.left));
  const visibleHeight = Math.max(0, Math.min(rect.bottom, rootRect.bottom) - Math.max(rect.top, rootRect.top));
  return (visibleWidth * visibleHeight) / (rect.width * rect.height);
}

let narratorVideoSyncRaf = null;
const NARRATOR_VIDEO_VISIBLE_THRESHOLD = 0.12;

function syncNarratorVideos() {
  narratorVideoSyncRaf = null;
  if (!narText) return;

  const videos = Array.from(narText.querySelectorAll('video[data-narrator-video-managed="1"]'));
  if (!videos.length) return;

  const canPlayInline = nar?.classList.contains('show')
    && !document.hidden;

  if (!canPlayInline) {
    pauseNarratorVideos();
    return;
  }

  videos.forEach(video => {
    const ratio = getNarratorVideoVisibleRatio(video);
    if (ratio >= NARRATOR_VIDEO_VISIBLE_THRESHOLD) {
      hydrateDeferredVideo(video);
      video.play?.().catch(() => {});
    } else {
      video.pause?.();
    }
  });
}

function requestNarratorVideoSync() {
  if (narratorVideoSyncRaf) return;
  const schedule = window.requestAnimationFrame || (callback => window.setTimeout(callback, 16));
  narratorVideoSyncRaf = schedule(syncNarratorVideos);
}

function deferNarratorVideoSources(video) {
  if (video.dataset.bgSrc || video.querySelector?.('source[data-bg-src]')) return;

  const src = video.getAttribute('src');
  if (src) {
    video.dataset.bgSrc = src;
    video.removeAttribute('src');
  }

  video.querySelectorAll?.('source[src]').forEach(source => {
    const sourceSrc = source.getAttribute('src');
    if (!sourceSrc) return;
    source.dataset.bgSrc = sourceSrc;
    source.removeAttribute('src');
  });
}

function prepareNarratorVideoPlayback(root) {
  if (!narText || !root) return;

  root.querySelectorAll?.('video').forEach(video => {
    if (video.dataset.narratorVideoManaged === '1') return;

    if (video.closest('.story-media-stack')) {
      video.muted = true;
      video.defaultMuted = true;
      video.autoplay = true;
      video.loop = true;
      video.playsInline = true;
      video.preload = 'auto';
      video.setAttribute('muted', '');
      video.setAttribute('playsinline', '');
      video.setAttribute('loop', '');
      video.setAttribute('preload', 'auto');
      hydrateDeferredVideo(video);
      video.load?.();
      video.play?.().catch(() => {});
      return;
    }

    video.dataset.narratorVideoManaged = '1';
    if (video.closest('.story-inline-media')) {
      video.muted = true;
      video.defaultMuted = true;
      video.autoplay = true;
      video.loop = true;
      video.playsInline = true;
      video.preload = 'auto';
      video.setAttribute('muted', '');
      video.setAttribute('playsinline', '');
      video.setAttribute('loop', '');
      video.setAttribute('preload', 'auto');
      hydrateDeferredVideo(video);
      video.load?.();
      const playPromise = video.play?.();
      playPromise?.catch?.(() => {});
      return;
    }

    video.removeAttribute('autoplay');
    video.autoplay = false;
    video.muted = true;
    video.defaultMuted = true;
    video.playsInline = true;
    video.setAttribute('muted', '');
    video.setAttribute('playsinline', '');
    video.preload = 'none';
    deferNarratorVideoSources(video);
    updateMediaLoadbox(video, 'loading');
    video.pause?.();
    video.load?.();
  });

  requestNarratorVideoSync();
}

function isNarratorSpacerPart(part) {
  return /^<div\b/i.test(part)
    && /height\s*:\s*12px/i.test(part)
    && !/<(img|video|picture|iframe)\b/i.test(part);
}

function isNarratorMediaPart(part) {
  return part.startsWith('<')
    && (/<(img|video|picture|iframe)\b/i.test(part) || /expandable-media-container/i.test(part));
}

function buildNarratorStoryScenes(htmlText) {
  const parts = String(htmlText || '')
    .split('|||')
    .map(part => part.trim())
    .filter(Boolean)
    .filter(part => !isNarratorSpacerPart(part));

  const scenes = [];
  let current = null;

  parts.forEach(part => {
    if (isNarratorMediaPart(part)) {
      if (!current) current = { text: '', media: [] };
      current.media.push(part);
      return;
    }

    if (current && (current.text || current.media.length)) {
      scenes.push(current);
    }
    current = { text: part, media: [] };
  });

  if (current && (current.text || current.media.length)) {
    scenes.push(current);
  }

  return scenes.length ? scenes : [{ text: String(htmlText || '').trim(), media: [] }];
}

function getNarratorStoryScrollRatio() {
  narVirtualMaxScroll = measureNarratorMaxScroll();
  const maxScroll = getNarratorTrackMaxScroll();
  if (narratorStoryDone && isNarratorNearBottom(8)) return 1;
  if (maxScroll <= 2) return narratorStoryDone ? 1 : 0;
  const scrollRatio = Math.max(0, Math.min(1, narVirtualScrollTop / maxScroll));
  if (narratorStoryDone) return scrollRatio;
  const revealedLimit = Math.max(.08, narratorStoryRevealedCount / Math.max(1, narratorStoryScenes.length));
  return Math.min(scrollRatio, revealedLimit);
}

function updateNarratorStoryProgress() {
  const total = Math.max(1, narratorStoryScenes.length);
  const ratio = getNarratorStoryScrollRatio();
  const progressPosition = ratio * total;
  const activeIndex = ratio >= .999
    ? total - 1
    : Math.max(0, Math.min(total - 1, Math.floor(progressPosition)));
  narratorStoryIndex = activeIndex;
  storyActiveProgress = Math.max(.08, Math.min(1, progressPosition - activeIndex || (ratio <= 0 ? .08 : 0)));

  if (storyCounter) {
    storyCounter.textContent = `${String(activeIndex + 1).padStart(2, '0')} / ${String(total).padStart(2, '0')}`;
  }
  if (storyPrev) storyPrev.disabled = narVirtualScrollTop <= 2;
  if (storyNext) storyNext.disabled = isNarratorNearBottom(2);

  if (!storyProgress) return;
  storyProgress.style.setProperty('--story-count', total);
  storyProgress.replaceChildren();
  for (let i = 0; i < total; i++) {
    const segment = document.createElement('span');
    segment.className = 'story-progress-segment';
    const fill = Math.max(0, Math.min(1, progressPosition - i));
    const safeFill = (i === 0 && ratio <= 0 && !narratorStoryDone) ? .08 : fill;
    if (safeFill >= .999) segment.classList.add('is-seen');
    if (i === activeIndex) {
      segment.classList.add('is-active');
      segment.style.setProperty('--story-fill', String(Math.max(.08, Math.min(1, safeFill))));
    } else {
      segment.style.setProperty('--story-fill', String(safeFill));
    }
    storyProgress.appendChild(segment);
  }
}

function updateStoryScrollbar() {
  if (!narText || !storyScrollbar || !storyScrollbarThumb) return;
  const track = storyScrollbar.querySelector('.story-scrollbar-track');
  if (!track) return;

  narVirtualMaxScroll = measureNarratorMaxScroll();
  const hasCurrentOverflow = narVirtualMaxScroll > 2;
  const trackHeight = track.clientHeight || 1;
  const viewportHeight = getNarratorScrollViewportHeight();
  const ratio = narVirtualMaxScroll > 0 ? narVirtualScrollTop / narVirtualMaxScroll : 0;
  const thumbHeight = narVirtualMaxScroll > 0
    ? Math.max(34, Math.min(trackHeight, trackHeight * (viewportHeight / (viewportHeight + narVirtualMaxScroll))))
    : trackHeight;
  const thumbY = Math.max(0, (trackHeight - thumbHeight) * ratio);

  storyScrollbarThumb.style.height = `${thumbHeight}px`;
  storyScrollbarThumb.style.transform = `translateY(${thumbY}px)`;
  storyScrollbar.classList.toggle('is-hidden', !hasCurrentOverflow);
  storyScrollbar.style.opacity = hasCurrentOverflow ? '1' : '0';
}

function syncStoryProgressToScroll() {
  syncNarratorVirtualScrollState();
  updateNarratorStoryProgress();
  updateStoryScrollbar();
}

function requestStoryScrollSync() {
  if (storyScrollSyncRaf) return;
  storyScrollSyncRaf = requestAnimationFrame(() => {
    storyScrollSyncRaf = null;
    syncStoryProgressToScroll();
  });
}

function clearStoryCaseReelTimers() {
  clearTimeout(storyCaseReelTimer);
  storyCaseReelActiveRoot?.classList.remove('is-touch-paused');
  storyCaseReelTimer = 0;
  storyCaseReelStartedAt = 0;
  storyCaseReelRemaining = 0;
}

function getWorkVisualImage(work) {
  const img = work?.querySelector?.('.work-visual img, .work-visual picture img');
  return img?.currentSrc || img?.getAttribute('src') || '';
}

function scheduleStoryCaseReelNext(delay) {
  clearTimeout(storyCaseReelTimer);
  storyCaseReelRemaining = delay;
  storyCaseReelStartedAt = Date.now();
  storyCaseReelTimer = setTimeout(() => {
    if (!storyCaseReelActiveRoot || !storyCaseReelActiveScenes) return;
    showStoryCaseReelScene(
      storyCaseReelActiveRoot,
      storyCaseReelActiveScenes,
      (storyCaseReelActiveIndex + 1) % storyCaseReelActiveScenes.length
    );
  }, delay);
}

function pauseStoryCaseReel() {
  if (!storyCaseReelTimer) return;
  clearTimeout(storyCaseReelTimer);
  storyCaseReelTimer = 0;
  storyCaseReelRemaining = Math.max(400, storyCaseReelRemaining - (Date.now() - storyCaseReelStartedAt));
}

function resumeStoryCaseReel() {
  if (storyCaseReelTimer || !storyCaseReelActiveRoot || !storyCaseReelActiveScenes) return;
  scheduleStoryCaseReelNext(storyCaseReelRemaining || 1200);
}

function canUseStoryCaseReelHover() {
  return window.matchMedia?.('(hover:hover) and (pointer:fine)')?.matches;
}

function isFreshStoryCaseReelTouch(pointerType, pointerAt) {
  return (pointerType === 'touch' || pointerType === 'pen') && Date.now() - pointerAt < 900;
}

function shouldUseStoryCaseReelTouchMode(pointerType, pointerAt = Date.now()) {
  return isFreshStoryCaseReelTouch(pointerType, pointerAt) || (!pointerType && !canUseStoryCaseReelHover());
}

function switchStoryCaseReelToMouse(root) {
  if (!root?.classList.contains('is-touch-paused')) return;
  root.classList.remove('is-touch-paused');
  resumeStoryCaseReel();
}

function pauseStoryCaseReelOnPointer(e) {
  if (e.pointerType !== 'mouse' || !canUseStoryCaseReelHover()) return;
  switchStoryCaseReelToMouse(e.currentTarget?.closest('.story-case-reel'));
  if (!e.currentTarget?.classList?.contains('is-active')) return;
  pauseStoryCaseReel();
}

function resumeStoryCaseReelOnPointer(e) {
  if (e.pointerType !== 'mouse' || !canUseStoryCaseReelHover()) return;
  switchStoryCaseReelToMouse(e.currentTarget?.closest('.story-case-reel'));
  if (!e.currentTarget?.classList?.contains('is-active')) return;
  resumeStoryCaseReel();
}

function pauseStoryCaseReelForTouch(root) {
  if (!root) return;
  root.classList.add('is-touch-paused');
  pauseStoryCaseReel();
}

function resumeStoryCaseReelFromTouch(root) {
  if (!root?.classList.contains('is-touch-paused')) return;
  root.classList.remove('is-touch-paused');
  resumeStoryCaseReel();
}

function resumeStoryCaseReelOnOutsideInput(e) {
  const root = storyCaseReelActiveRoot;
  if (!root?.classList.contains('is-touch-paused')) return;
  if (e.target.closest?.('.story-case-reel-nav')) return;

  if (e.pointerType === 'mouse' && canUseStoryCaseReelHover()) {
    switchStoryCaseReelToMouse(root);
    return;
  }

  if (!shouldUseStoryCaseReelTouchMode(e.pointerType)) return;
  resumeStoryCaseReelFromTouch(root);
}

document.addEventListener('pointerdown', resumeStoryCaseReelOnOutsideInput, true);

function showStoryCaseReelScene(root, scenes, sceneIndex = 0) {
  const scene = scenes[sceneIndex];
  if (!root || !scene) return;

  const duration = Math.min(9600, Math.max(5200, 1700 + Array.from(scene.text).length * 28));
  storyCaseReelActiveRoot = root;
  storyCaseReelActiveScenes = scenes;
  storyCaseReelActiveIndex = sceneIndex;
  root.style.setProperty('--scene-ms', `${duration}ms`);
  root.querySelector('.story-case-reel-label').textContent = scene.label;
  root.querySelector('.story-case-reel-count').textContent = scene.index;
  root.querySelector('.story-case-reel-text').textContent = scene.text;
  setCaseReelStrip(root.querySelector('.story-case-reel-strip'), scene);

  const nav = root.querySelector('.story-case-reel-nav');
  const buttons = Array.from(nav.querySelectorAll('.story-case-reel-step'));
  buttons.forEach(button => button.classList.remove('is-active'));
  void nav.offsetWidth;
  buttons.forEach((button, index) => {
    button.classList.toggle('is-active', index === sceneIndex);
  });

  scheduleStoryCaseReelNext(duration);
  if (root.classList.contains('is-touch-paused')) {
    pauseStoryCaseReel();
  }
  if (canUseStoryCaseReelHover() && buttons[sceneIndex]?.matches(':hover')) {
    pauseStoryCaseReel();
  }
}

function renderStoryCaseReel(mediaStack, work = currentNarWork) {
  if (!mediaStack) return false;
  const scenes = getCaseReelScenes(work);
  if (!scenes.length) return false;

  pauseNarratorVideos();
  releaseLoadedMedia(mediaStack);
  clearStoryCaseReelTimers();
  mediaStack.replaceChildren();
  mediaStack.classList.remove('is-empty', 'has-stage-media', 'is-activating');
  mediaStack.classList.add('is-case-reel');

  const reel = document.createElement('div');
  reel.className = 'story-case-reel';
  const visualSrc = getWorkVisualImage(work);
  if (visualSrc) reel.style.setProperty('--case-reel-bg', `url("${visualSrc}")`);
  reel.innerHTML = `
    <div class="story-case-reel-top">
      <div class="story-case-reel-count"></div>
    </div>
    <div class="story-case-reel-stage">
      <div class="story-case-reel-label"></div>
      <div class="story-case-reel-text"></div>
      <div class="story-case-reel-strip" aria-hidden="true"></div>
    </div>
    <div class="story-case-reel-nav"></div>
  `;
  const nav = reel.querySelector('.story-case-reel-nav');
  reel.addEventListener('pointermove', e => {
    if (e.pointerType !== 'mouse' || !canUseStoryCaseReelHover()) return;
    switchStoryCaseReelToMouse(reel);
  });
  reel.addEventListener('pointerdown', e => {
    if (e.pointerType === 'mouse' && canUseStoryCaseReelHover()) {
      switchStoryCaseReelToMouse(reel);
      return;
    }
    if (!shouldUseStoryCaseReelTouchMode(e.pointerType)) return;
    if (e.target.closest('.story-case-reel-nav')) return;
    resumeStoryCaseReelFromTouch(reel);
  });
  scenes.forEach((scene, sceneIndex) => {
    const btn = document.createElement('button');
    btn.className = 'story-case-reel-step';
    btn.type = 'button';
    btn.textContent = scene.label;
    let lastPointerType = '';
    let lastPointerAt = 0;
    btn.addEventListener('pointerdown', e => {
      lastPointerType = e.pointerType || '';
      lastPointerAt = Date.now();
      if (e.pointerType === 'mouse' && canUseStoryCaseReelHover()) {
        switchStoryCaseReelToMouse(reel);
      }
    });
    btn.addEventListener('click', e => {
      e.preventDefault();
      const useTouchPause = shouldUseStoryCaseReelTouchMode(lastPointerType, lastPointerAt);
      if (!useTouchPause) {
        switchStoryCaseReelToMouse(reel);
      }
      showStoryCaseReelScene(reel, scenes, sceneIndex);
      if (useTouchPause) {
        pauseStoryCaseReelForTouch(reel);
      }
      lastPointerType = '';
      lastPointerAt = 0;
      playUI('switch');
    });
    btn.addEventListener('pointerenter', pauseStoryCaseReelOnPointer);
    btn.addEventListener('pointerleave', resumeStoryCaseReelOnPointer);
    nav.appendChild(btn);
  });

  mediaStack.appendChild(reel);
  showStoryCaseReelScene(reel, scenes, 0);
  return true;
}

function buildStoryStagePlaceholder(mediaStack) {
  mediaStack.replaceChildren();
  clearStoryCaseReelTimers();
  mediaStack.classList.remove('is-activating');
  mediaStack.classList.remove('is-case-reel', 'has-stage-media');
  mediaStack.classList.add('is-empty');

  const placeholder = document.createElement('div');
  placeholder.className = 'story-media-placeholder';
  placeholder.textContent = String(narratorStoryIndex + 1).padStart(2, '0');
  mediaStack.appendChild(placeholder);
}

function clearStoryStageCarousels(root) {
  if (!root) return;
  root.querySelectorAll?.('.story-stage-carousel[data-story-carousel-interval-id]').forEach(visual => {
    const intervalId = Number(visual.dataset.storyCarouselIntervalId);
    if (intervalId) {
      clearInterval(intervalId);
      activeIntervals = activeIntervals.filter(id => id !== intervalId);
    }
    delete visual.dataset.storyCarouselIntervalId;
  });
}

function initStoryStageCarousels(root = document) {
  const carousels = root.querySelectorAll?.('.story-stage-carousel[data-social-carousel]') || [];

  carousels.forEach(visual => {
    if (visual.dataset.storyStageCarouselReady === '1') return;
    const slides = Array.from(visual.children)
      .filter(slide => slide.matches?.('img, video'));
    if (!slides.length) return;

    visual.dataset.storyStageCarouselReady = '1';
    visual.dataset.socialCarouselReady = '1';

    let activeIndex = 0;
    let isTransitioning = false;
    const interval = Math.max(1500, Number(visual.dataset.socialCarouselInterval) || 2200);
    const transitionMs = 700;

    function setSlidePosition(slide, offset, animate = true) {
      const travel = offset === 0
        ? '0'
        : offset > 0
          ? 'calc(100% + 3px)'
          : 'calc(-100% - 3px)';
      slide.style.transition = animate ? '' : 'none';
      slide.style.transform = `translate3d(${travel}, 0, 0)`;
    }

    function clearSlideVisibilityOverride(slide) {
      slide.style.opacity = '';
      slide.style.visibility = '';
    }

    function hideSlideInstantly(slide, offset = 1) {
      slide.style.transition = 'none';
      slide.style.opacity = '0';
      slide.style.visibility = 'hidden';
      setSlidePosition(slide, offset, false);
    }

    function setActiveSlide(nextIndex, animate = true) {
      const normalizedIndex = (nextIndex + slides.length) % slides.length;
      if (isTransitioning || (normalizedIndex === activeIndex && animate)) return;

      if (!animate || slides.length < 2) {
        activeIndex = normalizedIndex;
        slides.forEach((slide, index) => {
          const isActive = index === normalizedIndex;
          if (isActive) clearSlideVisibilityOverride(slide);
          slide.classList.toggle('social-carousel-active', isActive);
          slide.classList.remove('social-carousel-exiting');
          slide.setAttribute('aria-hidden', isActive ? 'false' : 'true');
          setSlidePosition(slide, isActive ? 0 : 1, false);
        });
        requestAnimationFrame(() => slides.forEach(slide => {
          slide.style.transition = '';
        }));
        return;
      }

      const previousIndex = activeIndex;
      const previousSlide = slides[previousIndex];
      const nextSlide = slides[normalizedIndex];
      isTransitioning = true;
      activeIndex = normalizedIndex;

      slides.forEach((slide, index) => {
        const isActive = index === normalizedIndex;
        const isExiting = index === previousIndex;
        if (isActive || isExiting) clearSlideVisibilityOverride(slide);
        slide.classList.toggle('social-carousel-active', isActive);
        slide.classList.toggle('social-carousel-exiting', isExiting);
        slide.setAttribute('aria-hidden', isActive ? 'false' : 'true');

        if (!isActive && !isExiting) {
          setSlidePosition(slide, 1, false);
        }
      });

      setSlidePosition(nextSlide, 1, false);
      requestAnimationFrame(() => {
        setSlidePosition(previousSlide, -1);
        setSlidePosition(nextSlide, 0);
      });

      const timerId = setTimeout(() => {
        hideSlideInstantly(previousSlide, 1);
        previousSlide.classList.remove('social-carousel-exiting');
        slides.forEach((slide, index) => {
          if (index !== activeIndex && slide !== previousSlide) hideSlideInstantly(slide, 1);
        });
        requestAnimationFrame(() => slides.forEach(slide => {
          clearSlideVisibilityOverride(slide);
          slide.style.transition = '';
        }));
        isTransitioning = false;
      }, transitionMs);
      activeTimers.push(timerId);
    }

    setActiveSlide(0, false);
    if (slides.length < 2) return;

    const intervalId = setInterval(() => setActiveSlide(activeIndex + 1), interval);
    visual.dataset.storyCarouselIntervalId = String(intervalId);
    activeIntervals.push(intervalId);
  });
}

function showStoryStageMedia(mediaHtml) {
  const mediaStack = narText?.querySelector('.story-media-stack');
  if (!mediaStack || !mediaHtml) return;

  clearStoryCaseReelTimers();
  pauseNarratorVideos();
  releaseLoadedMedia(mediaStack);
  mediaStack.replaceChildren();
  mediaStack.classList.remove('is-empty');
  mediaStack.classList.remove('is-case-reel');
  mediaStack.classList.add('has-stage-media');
  mediaStack.classList.remove('is-activating');

  let closeBtn = null;
  if (!narratorSuppressCaseReel) {
    closeBtn = document.createElement('button');
    closeBtn.className = 'story-stage-close';
    closeBtn.type = 'button';
    closeBtn.setAttribute('aria-label', 'Return to the case description');
    closeBtn.textContent = '×';
    closeBtn.addEventListener('click', e => {
      e.preventDefault();
      e.stopPropagation();
      closeBtn.disabled = true;
      const activeItem = mediaStack.querySelector('.story-media-item.is-stage-active');
      const visual = mediaStack.closest('.story-visual');
      mediaStack.classList.add('is-activating');
      visual?.classList.add('is-launching');
      if (activeItem) {
        activeItem.style.animation = 'story-stage-depart .58s cubic-bezier(.55,0,.25,1) forwards';
      }
      setTimeout(() => {
        let storyReelRendered = false;
        try {
          storyReelRendered = renderStoryCaseReel(mediaStack, currentNarWork);
        } catch (error) {
          console.error('Story case reel failed:', error);
        }
        if (!storyReelRendered) buildStoryStagePlaceholder(mediaStack);
        visual?.classList.remove('is-launching');
      }, 520);
      playUI('switch');
    });
  }

  const item = document.createElement('div');
  item.className = 'story-media-item is-stage-active';
  item.innerHTML = getStoryStageMediaHtml(mediaHtml);
  if (item.querySelector('.story-stage-carousel')) {
    item.classList.add('has-stage-carousel');
  }
  if (closeBtn) mediaStack.appendChild(closeBtn);
  mediaStack.appendChild(item);
  initMediaPreloaders(item);
  initStoryStageCarousels(item);
  prepareNarratorVideoPlayback(item);
  const visual = mediaStack.closest('.story-visual');
  visual?.classList.remove('is-launching');
  void mediaStack.offsetWidth;
  void visual?.offsetWidth;
  mediaStack.classList.add('is-activating');
  visual?.classList.add('is-launching');
  setTimeout(() => mediaStack.classList.remove('is-activating'), 940);
  setTimeout(() => visual?.classList.remove('is-launching'), 820);
  requestNarratorVideoSync();
  playUI('switch');
}

function getStoryInlineMediaHtml(mediaHtml) {
  const labelText = 'Click here to enlarge';
  if (/expandable-media-container/i.test(mediaHtml)) {
    const template = document.createElement('template');
    template.innerHTML = mediaHtml;
    const label = template.content.querySelector('.expandable-label');
    if (label) label.textContent = labelText;
    return template.innerHTML;
  }

  return `
    <div class="expandable-media-container">
      <svg class="emc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" color="var(--ion)">
        <path d="M8 3H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h3M16 3h3a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-3M9 17h6M9 13h6"/>
      </svg>
      <div class="emc-content">
        ${mediaHtml}
        <div class="expandable-label">Click here to enlarge</div>
      </div>
    </div>
  `;
}

function getStoryStageMediaHtml(mediaHtml) {
  const template = document.createElement('template');
  template.innerHTML = mediaHtml;
  const container = template.content.querySelector('.expandable-media-container');
  const content = container?.querySelector('.emc-content');
  if (!content) return mediaHtml;

  const clone = content.cloneNode(true);
  clone.querySelectorAll('.expandable-label').forEach(label => label.remove());
  return clone.innerHTML.trim() || mediaHtml;
}

let storyInlineMediaLayoutRaf = null;

function measureStoryMediaItemHeight(item, fallbackHeight) {
  if (!item) return fallbackHeight;
  const rectHeight = item.getBoundingClientRect().height;
  return Math.max(1, Math.round(rectHeight || item.scrollHeight || fallbackHeight));
}

function layoutStoryInlineMedia(inlineMedia) {
  if (!inlineMedia) return;
  const items = Array.from(inlineMedia.querySelectorAll('.story-media-item'))
    .sort((a, b) => Number(a.dataset.storyMediaIndex || 0) - Number(b.dataset.storyMediaIndex || 0));
  inlineMedia.style.removeProperty('width');
  const useMobileLayout = isNarratorMobileStoryLayout();
  const useCompactDesktopMedia = window.matchMedia?.('(min-width:951px) and (max-width:1120px)')?.matches;
  const rawAvailableWidth = inlineMedia.closest('.story-copy-body')?.clientWidth
    || inlineMedia.parentElement?.clientWidth
    || inlineMedia.getBoundingClientRect().width
    || 0;
  let availableWidth = rawAvailableWidth;
  if (useMobileLayout) {
    const inlineRect = inlineMedia.getBoundingClientRect();
    const feedRect = inlineMedia.closest('.story-feed')?.getBoundingClientRect();
    const narRect = narText?.getBoundingClientRect();
    const visibleRight = Math.min(
      feedRect?.right ?? Number.POSITIVE_INFINITY,
      narRect?.right ?? Number.POSITIVE_INFINITY
    );
    const visibleWidth = Number.isFinite(visibleRight)
      ? Math.max(0, visibleRight - inlineRect.left - 24)
      : rawAvailableWidth;
    availableWidth = Math.min(rawAvailableWidth, visibleWidth);
  }
  const preferredColWidth = useCompactDesktopMedia ? 190 : 208;
  const gap = (useMobileLayout || useCompactDesktopMedia) ? 10 : 12;
  const maxColumnCount = useMobileLayout ? 5 : 2;
  const columnReserve = useMobileLayout ? 12 : 0;
  const mobileMinColWidth = 156;
  const usableWidth = Math.max(0, availableWidth - columnReserve);
  const countColWidth = useMobileLayout ? mobileMinColWidth : preferredColWidth;
  const columnCount = availableWidth
    ? Math.max(1, Math.min(maxColumnCount, Math.floor((usableWidth + gap) / (countColWidth + gap))))
    : 1;
  const targetColWidth = useMobileLayout && columnCount > 1
    ? Math.max(mobileMinColWidth, Math.min(preferredColWidth, Math.floor((usableWidth - ((columnCount - 1) * gap)) / columnCount)))
    : preferredColWidth;
  const plannedItemCount = Math.max(items.length, Number(inlineMedia.dataset.mediaCount || 0));
  const useMasonry = plannedItemCount > 1 && columnCount > 1;

  inlineMedia.classList.toggle('is-masonry', useMasonry);
  inlineMedia.style.setProperty('--story-media-cols', String(columnCount));
  inlineMedia.style.setProperty('--story-media-col-width', `${targetColWidth}px`);
  if (!useMasonry) {
    inlineMedia.style.removeProperty('--story-media-cols');
    inlineMedia.style.removeProperty('--story-media-col-width');
    inlineMedia.style.removeProperty('width');
    items.forEach((item, index) => {
      const currentChild = inlineMedia.children[index];
      if (currentChild !== item) inlineMedia.insertBefore(item, currentChild || null);
    });
    Array.from(inlineMedia.querySelectorAll('.story-inline-media-col')).forEach(col => col.remove());
    return;
  }

  inlineMedia.style.width = `${(columnCount * targetColWidth) + ((columnCount - 1) * gap)}px`;
  const fallbackHeight = Math.round(targetColWidth * .72);
  const itemHeights = new Map(items.map(item => [
    item,
    measureStoryMediaItemHeight(item, fallbackHeight)
  ]));

  const existingColumns = Array.from(inlineMedia.children)
    .filter(child => child.classList?.contains('story-inline-media-col'));
  const columns = Array.from({ length:columnCount }, (_, index) => {
    const col = existingColumns[index] || document.createElement('div');
    col.className = 'story-inline-media-col';
    return col;
  });
  columns.forEach((col, index) => {
    const currentChild = inlineMedia.children[index];
    if (col.parentElement !== inlineMedia || currentChild !== col) {
      inlineMedia.insertBefore(col, currentChild || null);
    }
  });
  existingColumns.slice(columnCount).forEach(col => col.remove());
  const columnHeights = columns.map(() => 0);
  const desiredColumns = columns.map(() => []);

  items.forEach(item => {
    const itemHeight = itemHeights.get(item) || fallbackHeight;
    let targetIndex = 0;
    for (let i = 1; i < columnHeights.length; i += 1) {
      if (columnHeights[i] < columnHeights[targetIndex]) targetIndex = i;
    }
    desiredColumns[targetIndex].push(item);
    columnHeights[targetIndex] += itemHeight + gap;
  });

  desiredColumns.forEach((desiredItems, columnIndex) => {
    const col = columns[columnIndex];
    desiredItems.forEach((item, itemIndex) => {
      const currentChild = col.children[itemIndex];
      if (currentChild !== item) col.insertBefore(item, currentChild || null);
    });
    Array.from(col.children).forEach(child => {
      if (!desiredItems.includes(child)) child.remove();
    });
  });
}

function requestStoryInlineMediaLayout() {
  if (storyInlineMediaLayoutRaf) return;
  storyInlineMediaLayoutRaf = requestAnimationFrame(() => {
    storyInlineMediaLayoutRaf = null;
    narText?.querySelectorAll('.story-inline-media').forEach(layoutStoryInlineMediaSmooth);
    requestStoryScrollSync();
  });
}

function layoutStoryInlineMediaSmooth(inlineMedia) {
  layoutStoryInlineMedia(inlineMedia);
}

function requestStoryInlineMediaStableLayout(inlineMedia) {
  requestStoryInlineMediaLayout();
  requestAnimationFrame(() => requestAnimationFrame(() => {
    layoutStoryInlineMediaSmooth(inlineMedia);
    requestStoryScrollSync();
  }));
  setTimeout(() => {
    layoutStoryInlineMediaSmooth(inlineMedia);
    requestStoryScrollSync();
  }, 180);
}

function prepareStoryInlineMediaShell(inlineMedia, itemCount) {
  if (!inlineMedia || itemCount <= 1) return;
  const useMobileLayout = isNarratorMobileStoryLayout();
  const useCompactDesktopMedia = window.matchMedia?.('(min-width:951px) and (max-width:1120px)')?.matches;
  const rawAvailableWidth = inlineMedia.closest('.story-copy-body')?.clientWidth
    || inlineMedia.parentElement?.clientWidth
    || inlineMedia.getBoundingClientRect().width
    || 0;
  let availableWidth = rawAvailableWidth;
  if (useMobileLayout) {
    const inlineRect = inlineMedia.getBoundingClientRect();
    const feedRect = inlineMedia.closest('.story-feed')?.getBoundingClientRect();
    const narRect = narText?.getBoundingClientRect();
    const visibleRight = Math.min(
      feedRect?.right ?? Number.POSITIVE_INFINITY,
      narRect?.right ?? Number.POSITIVE_INFINITY
    );
    const visibleWidth = Number.isFinite(visibleRight)
      ? Math.max(0, visibleRight - inlineRect.left - 24)
      : rawAvailableWidth;
    availableWidth = Math.min(rawAvailableWidth, visibleWidth);
  }
  const preferredColWidth = useCompactDesktopMedia ? 190 : 208;
  const gap = (useMobileLayout || useCompactDesktopMedia) ? 10 : 12;
  const maxColumnCount = useMobileLayout ? 5 : 2;
  const columnReserve = useMobileLayout ? 12 : 0;
  const mobileMinColWidth = 156;
  const usableWidth = Math.max(0, availableWidth - columnReserve);
  const countColWidth = useMobileLayout ? mobileMinColWidth : preferredColWidth;
  const columnCount = availableWidth
    ? Math.max(1, Math.min(maxColumnCount, Math.floor((usableWidth + gap) / (countColWidth + gap))))
    : 1;
  if (columnCount <= 1) return;

  const targetColWidth = useMobileLayout && columnCount > 1
    ? Math.max(mobileMinColWidth, Math.min(preferredColWidth, Math.floor((usableWidth - ((columnCount - 1) * gap)) / columnCount)))
    : preferredColWidth;

  inlineMedia.classList.add('is-masonry');
  inlineMedia.style.setProperty('--story-media-cols', String(columnCount));
  inlineMedia.style.setProperty('--story-media-col-width', `${targetColWidth}px`);
  inlineMedia.style.width = `${(columnCount * targetColWidth) + ((columnCount - 1) * gap)}px`;

  const columns = Array.from({ length:columnCount }, () => {
    const col = document.createElement('div');
    col.className = 'story-inline-media-col';
    return col;
  });
  inlineMedia.replaceChildren(...columns);
}

function buildStoryInlineMedia(scene, inlineMedia, sceneIndex = 0) {
  if (!inlineMedia) return 0;
  inlineMedia.replaceChildren();
  inlineMedia.classList.remove('is-ready');
  inlineMedia.dataset.mediaCount = String(scene.media.length);

  if (!scene.media.length) return 0;
  prepareStoryInlineMediaShell(inlineMedia, scene.media.length);

  const items = scene.media.map((mediaHtml, mediaIndex) => {
    const item = document.createElement('button');
    item.className = 'story-media-item';
    item.type = 'button';
    item._storyMediaHtml = mediaHtml;
    item.dataset.storySceneIndex = String(sceneIndex);
    item.dataset.storyMediaIndex = String(mediaIndex);
    item.setAttribute('aria-label', 'Show media on stage');
    item.innerHTML = getStoryInlineMediaHtml(mediaHtml);
    item.querySelectorAll('.expandable-label').forEach(label => {
      label.textContent = 'Click here to enlarge';
    });
    item.addEventListener('click', e => {
      e.preventDefault();
      e.stopPropagation();
      showStoryStageMedia(item._storyMediaHtml || scene.media[mediaIndex]);
    });
    item.querySelectorAll('img').forEach(img => {
      if (img.complete) requestStoryInlineMediaStableLayout(inlineMedia);
      img.addEventListener('load', () => requestStoryInlineMediaStableLayout(inlineMedia), { once:true });
    });
    item.querySelectorAll('video').forEach(video => {
      if (video.readyState >= 1) requestStoryInlineMediaStableLayout(inlineMedia);
      video.addEventListener('loadedmetadata', () => requestStoryInlineMediaStableLayout(inlineMedia), { once:true });
    });
    return item;
  });

  const revealDelay = 230;
  const appendItem = index => {
    if (!inlineMedia.isConnected) return;
    const item = items[index];
    if (!item) return;

    const firstColumn = inlineMedia.querySelector('.story-inline-media-col');
    if (firstColumn) {
      firstColumn.appendChild(item);
    } else {
      inlineMedia.appendChild(item);
    }
    initMediaPreloaders(item);
    prepareNarratorVideoPlayback(item);
    layoutStoryInlineMediaSmooth(inlineMedia);
    inlineMedia.classList.add('is-ready');
    scrollNarratorToBottom();

    if (index < items.length - 1) {
      const timerId = setTimeout(() => appendItem(index + 1), revealDelay);
      activeTimers.push(timerId);
    } else {
      requestStoryInlineMediaStableLayout(inlineMedia);
    }
  };

  requestAnimationFrame(() => appendItem(0));
  return Math.max(0, (items.length - 1) * revealDelay + 760);
}

function typeNarratorStoryText(target, text, onComplete) {
  clearAllTimers();
  const chars = Array.from(text || '');
  const step = Math.max(2, Math.ceil(chars.length / 145));
  let cursor = 0;
  target.textContent = '';
  target.classList.add('is-typing');

  function tick() {
    cursor = Math.min(chars.length, cursor + step);
    target.textContent = chars.slice(0, cursor).join('');
    scrollNarratorToBottom();
    if (cursor < chars.length) {
      const timerId = setTimeout(tick, 8);
      activeTimers.push(timerId);
    } else {
      target.classList.remove('is-typing');
      onComplete?.();
    }
  }

  tick();
}

function createNarratorFeedScene(scene, index) {
  const sceneEl = document.createElement('article');
  sceneEl.className = 'story-feed-scene';
  if (index > 0) sceneEl.classList.add('is-continuation');
  sceneEl.classList.toggle('is-text-only', !scene.media.length);
  const kickerText = index === 0 ? 'STORY TRANSMISSION' : '&nbsp;';
  const linkHtml = getStoryCopyCtaHtml(scene.link);
  sceneEl.innerHTML = `
    <div class="story-copy">
      <div class="story-copy-kicker">${kickerText}</div>
      <div class="story-copy-body">
        <div class="story-copy-text"></div>
        ${linkHtml}
        <div class="story-inline-media"></div>
      </div>
    </div>
  `;

  return {
    el: sceneEl,
    textTarget: sceneEl.querySelector('.story-copy-text'),
    linkTarget: sceneEl.querySelector('.story-copy-cta'),
    inlineMedia: sceneEl.querySelector('.story-inline-media')
  };
}

function getStoryCopyCtaHtml(link, visible = false) {
  if (!link?.href) return '';
  const label = escapeHtmlText(link.label || 'Watch');
  return `
    <a class="motion-card-cta story-copy-cta${visible ? ' is-visible' : ''}" href="${escapeHtmlAttribute(link.href)}" target="_blank" rel="noopener noreferrer">
      <span>${label}</span>
      <svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true">
        <path d="M3 9L9 3M4 3h5v5" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>
    </a>
  `;
}

function buildNarratorMeasureLayout() {
  if (!narText) return;
  narText.querySelector('.story-measure-layout')?.remove();

  const measure = document.createElement('div');
  measure.className = 'story-scroll-layout story-measure-layout';
  measure.innerHTML = `
    <div class="story-visual story-measure-visual"></div>
    <div class="story-feed">
      <div class="story-feed-track"></div>
    </div>
  `;

  const feed = measure.querySelector('.story-feed-track');
  narratorStoryScenes.forEach((scene, index) => {
    const sceneEl = document.createElement('article');
    sceneEl.className = 'story-feed-scene';
    if (index > 0) sceneEl.classList.add('is-continuation');
    sceneEl.classList.toggle('is-text-only', !scene.media.length);
    const kickerText = index === 0 ? 'STORY TRANSMISSION' : '&nbsp;';
    const mediaHtml = scene.media.map(() => '<div class="story-media-item story-measure-media"></div>').join('');
    const linkHtml = getStoryCopyCtaHtml(scene.link, true);
    sceneEl.innerHTML = `
      <div class="story-copy">
        <div class="story-copy-kicker">${kickerText}</div>
        <div class="story-copy-body">
          <div class="story-copy-text"></div>
          ${linkHtml}
          <div class="story-inline-media is-ready">${mediaHtml}</div>
        </div>
      </div>
    `;
    sceneEl.querySelector('.story-copy-text').textContent = scene.text || '';
    feed.appendChild(sceneEl);
  });

  narText.appendChild(measure);
  narStoryEstimatedMaxScroll = measureNarratorLayoutMaxScroll(measure);
  requestAnimationFrame(() => {
    narStoryEstimatedMaxScroll = Math.max(narStoryEstimatedMaxScroll, measureNarratorLayoutMaxScroll(measure));
    requestStoryScrollSync();
  });
}

function renderNarratorStoryFeed(work = currentNarWork) {
  if (!narText || !narratorStoryScenes.length) return;

  pauseNarratorVideos();
  releaseLoadedMedia(narText);
  narText.innerHTML = '';
  resetNarratorAutoScroll();
  narratorStoryIndex = 0;
  storyActiveProgress = .08;
  narratorStoryRevealedCount = 0;

  const layout = document.createElement('div');
  layout.className = 'story-scroll-layout';
  layout.innerHTML = `
    <div class="story-visual">
      <div class="story-media-stack"></div>
    </div>
    <div class="story-feed">
      <div class="story-feed-track"></div>
    </div>
  `;
  narText.appendChild(layout);
  buildNarratorMeasureLayout();
  narVirtualScrollTop = 0;
  narVirtualMaxScroll = measureNarratorMaxScroll();
  applyNarratorVirtualScroll();

  const visual = layout.querySelector('.story-visual');
  const mediaStack = visual.querySelector('.story-media-stack');
  const feed = layout.querySelector('.story-feed-track');
  let storyReelRendered = false;
  if (!narratorSuppressCaseReel) {
    try {
      storyReelRendered = renderStoryCaseReel(mediaStack, work);
    } catch (error) {
      console.error('Story case reel failed:', error);
    }
  }
  if (!storyReelRendered) buildStoryStagePlaceholder(mediaStack);
  if (narratorInitialStageMediaHtml) {
    requestAnimationFrame(() => showStoryStageMedia(narratorInitialStageMediaHtml));
  }
  updateNarratorStoryProgress();

  function appendScene(index) {
    const scene = narratorStoryScenes[index];
    if (!scene) return;
    narratorStoryIndex = index;
    narratorStoryRevealedCount = Math.max(narratorStoryRevealedCount, index + 1);
    storyActiveProgress = .08;
    updateNarratorStoryProgress();

    const rendered = createNarratorFeedScene(scene, index);
    feed.appendChild(rendered.el);
    scrollNarratorToBottom();

    typeNarratorStoryText(rendered.textTarget, scene.text, () => {
      rendered.linkTarget?.classList.add('is-visible');
      const mediaRevealDuration = buildStoryInlineMedia(scene, rendered.inlineMedia, index);
      scrollNarratorToBottom();
      if (index < narratorStoryScenes.length - 1) {
        const nextSceneDelay = scene.media.length
          ? Math.max(520, mediaRevealDuration + 160)
          : 320;
        const timerId = setTimeout(() => appendScene(index + 1), nextSceneDelay);
        activeTimers.push(timerId);
      } else {
        narratorStoryDone = true;
        narratorStoryRevealedCount = narratorStoryScenes.length;
        narratorStoryIndex = Math.max(0, narratorStoryScenes.length - 1);
        storyActiveProgress = 1;
        narText?.querySelectorAll('.story-copy-text.is-typing').forEach(el => el.classList.remove('is-typing'));
        updateNarratorStoryProgress();
        requestStoryScrollSync();
      }
    });
  }

  appendScene(0);
}

function typeWriter(htmlText, work = currentNarWork, { initialStageMediaHtml = '', suppressCaseReel = false, storyLink = null } = {}) {
  if (!narText) return;
  currentNarWork = work;
  narratorInitialStageMediaHtml = initialStageMediaHtml;
  narratorSuppressCaseReel = suppressCaseReel;
  clearAllTimers();
  resetNarratorAutoScroll();
  clearNarratorContent();
  narratorStoryScenes = buildNarratorStoryScenes(htmlText);
  if (storyLink && narratorStoryScenes[0]) {
    narratorStoryScenes[0].link = storyLink;
  }
  narratorStoryIndex = 0;
  narratorStoryDone = false;
  renderNarratorStoryFeed(work);
}

window.addEventListener('resize', () => {
  requestNarratorVideoSync();
  requestStoryInlineMediaLayout();
  requestStoryScrollSync();
}, { passive: true });
document.addEventListener('visibilitychange', syncNarratorVideos);

function openNarratorModal() {
  if (!nar) return;
  if (!document.body.classList.contains('story-modal-open')) {
    narratorPageScrollY = window.scrollY || document.documentElement.scrollTop || 0;
    document.body.style.top = `-${narratorPageScrollY}px`;
  }
  nar.classList.add('show');
  nar.setAttribute('aria-hidden', 'false');
  document.documentElement.classList.add('story-modal-open');
  document.body.classList.add('story-modal-open');
  syncAllViewportVideos();
  requestNarratorVideoSync();
}

function closeNarratorModal({ hidden = true, restoreFocus = true } = {}) {
  clearAllTimers();
  const wasPageLocked = document.body.classList.contains('story-modal-open');
  if (nar) {
    nar.classList.remove('show');
    nar.setAttribute('aria-hidden', 'true');
  }
  document.documentElement.classList.remove('story-modal-open');
  document.body.classList.remove('story-modal-open');
  syncAllViewportVideos();
  const previousRootScrollBehavior = document.documentElement.style.scrollBehavior;
  const previousBodyScrollBehavior = document.body.style.scrollBehavior;
  document.documentElement.style.scrollBehavior = 'auto';
  document.body.style.scrollBehavior = 'auto';
  document.body.style.top = '';
  if (wasPageLocked) {
    window.scrollTo({ top:narratorPageScrollY, left:0, behavior:'auto' });
  }
  requestAnimationFrame(() => {
    document.documentElement.style.scrollBehavior = previousRootScrollBehavior;
    document.body.style.scrollBehavior = previousBodyScrollBehavior;
  });
  storyTouchLastY = null;
  clearNarratorContent();
  narHidden = hidden;
  currentNarWork = null;
  narratorInitialStageMediaHtml = '';
  narratorSuppressCaseReel = false;
  narratorStoryScenes = [];
  narratorStoryIndex = 0;
  narratorStoryDone = false;
  narratorStoryRevealedCount = 0;
  storyActiveProgress = 1;
  updateNarratorStoryProgress();
  if (restoreFocus && narratorLastTrigger?.focus) {
    narratorLastTrigger.focus({ preventScroll: true });
  }
  narratorLastTrigger = null;
}

// Show narrator on Details button click
function showNarrator(workElement) {
  if (!nar || !narText || !narFrom) return;
  clearAllTimers();
  narratorLastTrigger = document.activeElement;
  currentNarWork = workElement;
  narText.style.opacity = '0';
  const timerId = setTimeout(() => {
    narFrom.textContent = '— ' + workElement.querySelector('.w-title').textContent;
    narText.style.opacity = '1';
    openNarratorModal();
    typeWriter(workElement.dataset.narrator, workElement);
  }, 260);
  activeTimers.push(timerId);
}

function escapeHtmlAttribute(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escapeHtmlText(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function getMotionCardDetails(caseId) {
  const safeCaseId = window.CSS?.escape ? CSS.escape(String(caseId || '')) : String(caseId || '').replace(/"/g, '\\"');
  const cardEl = safeCaseId ? document.querySelector(`.motion-card[data-case-id="${safeCaseId}"]`) : null;
  if (!cardEl) return null;
  const link = cardEl.querySelector('.motion-card-cta[href]');
  return {
    name: cleanAnalyticsText(cardEl.querySelector('.motion-card-title')?.textContent),
    desc: cleanAnalyticsText(cardEl.querySelector('.motion-card-desc')?.textContent),
    linkHref: link?.href || '',
    linkLabel: cleanAnalyticsText(link?.textContent) || 'Watch'
  };
}

function getRecommendedContentDetails(card) {
  if (!card?.caseId) return null;
  const type = String(card.type || '').trim().toLowerCase();
  if (type === 'video') return getMotionCardDetails(card.caseId);

  const safeCaseId = window.CSS?.escape ? CSS.escape(String(card.caseId || '')) : String(card.caseId || '').replace(/"/g, '\\"');
  const sourceEl = safeCaseId
    ? document.querySelector(`.social-post[data-case-id="${safeCaseId}"], .printed-item[data-case-id="${safeCaseId}"]`)
    : null;
  if (!sourceEl) return null;

  const visual = sourceEl.querySelector('.post-visual, .printed-visual');
  const aspectRatio = visual?.style?.aspectRatio || '';
  const mediaSources = Array.from(visual?.querySelectorAll('img, video') || [])
    .map(media => media.dataset.bgSrc || media.currentSrc || media.src || '')
    .filter(Boolean);

  return {
    name: cleanAnalyticsText(sourceEl.querySelector('.printed-title')?.textContent || card.name),
    desc: cleanAnalyticsText(sourceEl.querySelector('.post-caption, .printed-desc')?.textContent || card.desc),
    aspectRatio,
    mediaSources,
    linkHref: '',
    linkLabel: ''
  };
}

function getAiMediaNarratorText(card, sourceDetails = null) {
  const name = cleanAnalyticsText(sourceDetails?.name || card?.name || '');
  const desc = cleanAnalyticsText(sourceDetails?.desc || card?.desc || '');
  return desc ? `${name}. ${desc}` : name;
}

function getAiStageCarouselHtml(card, sourceDetails = null) {
  const carouselSources = sourceDetails?.mediaSources?.length > 1
    ? sourceDetails.mediaSources
    : card?.images || [];
  const sources = carouselSources
    .map(src => escapeHtmlAttribute(src))
    .filter(Boolean);
  if (sources.length < 2) return '';

  const aspectRatio = escapeHtmlAttribute(sourceDetails?.aspectRatio || '');
  const styleAttr = aspectRatio ? ` style="aspect-ratio:${aspectRatio}"` : '';
  return `
    <div class="post-visual story-stage-carousel" data-social-carousel data-social-carousel-interval="2200"${styleAttr}>
      ${sources.map(src => `<img src="${src}" alt="">`).join('')}
    </div>
  `;
}

function getAiStageMediaHtml(card, sourceDetails = null) {
  const carouselHtml = getAiStageCarouselHtml(card, sourceDetails);
  if (carouselHtml) return carouselHtml;

  const src = escapeHtmlAttribute(card?.video || card?.image || '');
  if (!src) return '';
  if (!card?.video && card?.image) {
    return `<img src="${src}" alt="" style="width:100%; height:auto; display:block; border-radius:5px;">`;
  }
  return `<video autoplay muted playsinline loop preload="auto" src="${src}" style="width:100%; height:auto; display:block; border-radius:5px;"></video>`;
}

function showAiMediaNarrator(card) {
  const hasMedia = Boolean(card?.video || card?.image || (Array.isArray(card?.images) && card.images.length));
  if (!nar || !narText || !narFrom || !hasMedia) return false;
  const sourceDetails = getRecommendedContentDetails(card);
  trackEvent(
    `media narrator opened: ${cleanAnalyticsText(card.caseId || card.name || 'unknown media')}; ` +
    `type: ${cleanAnalyticsText(card.type || 'media')}; ` +
    `title: ${cleanAnalyticsText(sourceDetails?.name || card.name || '')}; ` +
    `link: ${sourceDetails?.linkHref ? cleanAnalyticsText(sourceDetails.linkHref) : 'none'}`
  );
  clearAllTimers();
  narratorLastTrigger = document.activeElement;
  currentNarWork = null;
  narHidden = false;
  narText.style.opacity = '0';
  const timerId = setTimeout(() => {
    narFrom.textContent = '— ' + (sourceDetails?.name || card.name || 'Video');
    narText.style.opacity = '1';
    openNarratorModal();
    typeWriter(getAiMediaNarratorText(card, sourceDetails), null, {
      initialStageMediaHtml: getAiStageMediaHtml(card, sourceDetails),
      suppressCaseReel: true,
      storyLink: sourceDetails?.linkHref
        ? { href: sourceDetails.linkHref, label: sourceDetails.linkLabel }
        : null
    });
  }, 260);
  activeTimers.push(timerId);
  return true;
}

function showProductCaseNarrator() {
  if (!nar || !narText || !narFrom) return;
  clearAllTimers();
  narratorLastTrigger = document.activeElement;
  const productStoryWork = document.querySelector('.product-case-section, [data-case-id="product-case"]');
  currentNarWork = productStoryWork;
  narHidden = false;
  narText.style.opacity = '0';
  const timerId = setTimeout(() => {
    narFrom.textContent = '— Space story';
    narText.style.opacity = '1';
    openNarratorModal();
    currentNarWork = productStoryWork;
    typeWriter('I had an idea: a cosmic sci-fi experience with control panels and a layered narrative. The concept felt deep, and with careful visuals, it should have attracted attention and encouraged collaboration on its own. The message was: look, here is a creative specialist with a strong technical base. ||| <div style="height:12px;"></div> ||| But after the website launched, the feedback was far from what I expected. I saw that people visited the site, but they did not stay or return. ||| <div style="height:12px;"></div> ||| I was upset. But I did not step back. Okay, the result was unsatisfactory, but now I knew the site had low conversion. You are a designer. You know what to do with low conversion. ||| <div style="height:12px;"></div> ||| I needed to dig deeper. I attached logging to key actions. I did it carefully and minimally to avoid violating GDPR. Then I looked at the logs. ||| <div style="height:12px;"></div> ||| The first destructive element was onboarding. Earlier, I thought a detailed 9-step tour with animation mode selection and a story about me as a person was a great idea. But users did not want to read that much. They simply left the site before even scrolling down to the work. This is how it looked at the beginning: ||| <div class="expandable-media-container"><svg class="emc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" color="var(--ion)"><path d="M8 3H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h3M16 3h3a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-3M9 17h6M9 13h6"/></svg><div class="emc-content"><video autoplay muted playsinline loop src="./productCase/firstIteration.mp4" style="width:100%; height:auto; display:block; border-radius: 5px;"></video><div class="expandable-label">Click here to enlarge</div></div></div> ||| I started reshaping the onboarding. The work became closer to the user. Now only the animation mode stood between them and the page, while the rest of onboarding was reduced to 4 steps and shown exactly where it mattered: next to the cases section. ||| <div class="expandable-media-container"><svg class="emc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" color="var(--ion)"><path d="M8 3H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h3M16 3h3a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-3M9 17h6M9 13h6"/></svg><div class="emc-content"><video autoplay muted playsinline loop src="./productCase/secondIteration.mp4" style="width:100%; height:auto; display:block; border-radius: 5px;"></video><div class="expandable-label">Click here to enlarge</div></div></div> |||  In the logs, I saw that people started scrolling deeper and clicking on cases. A few emails from recruiters came in. So I was moving in the right direction. From that point on, I wanted the main screen to be open immediately, without any overlay blocking it. To make that work, I had to solve the animation mode problem. It mattered because weaker devices cannot handle many transformations, endless autoplay, and heavy media batches. First, I optimized the page’s media management with Codex by OpenAI. Second, I created a script that automatically adapts the animation mode to the device’s capabilities. Finally, the user flow became logical, and nothing blocks the main page: ||| <div class="expandable-media-container"><svg class="emc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" color="var(--ion)"><path d="M8 3H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h3M16 3h3a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-3M9 17h6M9 13h6"/></svg><div class="emc-content"><video autoplay muted playsinline loop src="./productCase/thirdIteration.mp4" style="width:100%; height:auto; display:block; border-radius: 5px;"></video><div class="expandable-label">Click here to enlarge</div></div></div> ||| The logs became consistently better, although conversion was still not where I wanted it to be. That led me to the next important change: diversifying the UX. Before, the page was rich in material, but visually too uniform. There was no wow effect. And that is exactly what helps cultivate the impulse to collaborate. Today, anyone can make a website, even if it looks templated. But not everyone can design a unique user experience. So I added the surprise section, artificial intelligence, and normalized the case visuals. ||| <div style="height:12px;"></div> ||| Before, it looked like this: ||| <div class="expandable-media-container"><svg class="emc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" color="var(--ion)"><path d="M8 3H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h3M16 3h3a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-3M9 17h6M9 13h6"/></svg><div class="emc-content"><video autoplay muted playsinline loop src="./productCase/fourthIterationBefore.mp4" style="width:100%; height:auto; display:block; border-radius: 5px;"></video><div class="expandable-label">Click here to enlarge</div></div></div> ||| And now it looks like this: ||| <div class="expandable-media-container"><svg class="emc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" color="var(--ion)"><path d="M8 3H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h3M16 3h3a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-3M9 17h6M9 13h6"/></svg><div class="emc-content"><video autoplay muted playsinline loop src="./productCase/fourthIterationAfter.mp4" style="width:100%; height:auto; display:block; border-radius: 5px;"></video><div class="expandable-label">Click here to enlarge</div></div></div> ||| And this is still far from the finish line. I continue to study user behavior, experiment, and develop my product. Despite the difficulties of war in the place where I live now, despite fear, despite the poor initial feedback. This story probably describes my way of thinking best. I do not step back when I see failure. I try to understand why it happened and how to change the system to succeed. I believe this is the mindset of a real product designer, the kind I want to become.');
  }, 160);
  activeTimers.push(timerId);
}

