function triggerDetailsButtonShimmer(btn) {
  if (!btn) return;
  btn.classList.remove('details-btn-shimmer');
  void btn.offsetWidth;
  btn.classList.add('details-btn-shimmer');
  setTimeout(() => btn.classList.remove('details-btn-shimmer'), 3300);
}

function initDetailsButtonShimmer() {
  const buttons = Array.from(document.querySelectorAll('.work .details-btn'));
  if (!buttons.length) return;

  let fired = false;
  const fire = btn => {
    if (fired || !btn) return;
    fired = true;
    triggerDetailsButtonShimmer(btn);
  };

  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver(entries => {
      const visibleEntry = entries
        .filter(entry => entry.isIntersecting)
        .sort((a, b) => buttons.indexOf(a.target) - buttons.indexOf(b.target))[0];
      if (!visibleEntry) return;
      fire(visibleEntry.target);
      observer.disconnect();
    }, { rootMargin:'0px 0px -20% 0px', threshold:.01 });
    buttons.forEach(btn => observer.observe(btn));
    requestAnimationFrame(() => {
      if (fired) return;
      const visibleButton = buttons.find(button => {
        const rect = button.getBoundingClientRect();
        return rect.bottom > 0 && rect.top < window.innerHeight;
      });
      if (!visibleButton) return;
      fire(visibleButton);
      observer.disconnect();
    });
    return;
  }

  const check = (allowAnyVisible = false) => {
    const allowVisibleViewport = allowAnyVisible === true;
    const btn = buttons.find(button => {
      const rect = button.getBoundingClientRect();
      return rect.bottom > 0 && (allowVisibleViewport ? rect.top < window.innerHeight : rect.top <= window.innerHeight * .8);
    });
    if (!btn) return;
    fire(btn);
    window.removeEventListener('scroll', check);
    window.removeEventListener('resize', check);
  };
  requestAnimationFrame(() => check(true));
  window.addEventListener('scroll', check, { passive:true });
  window.addEventListener('resize', check);
}

function observeAnalyticsScrollIn(selector, eventName) {
  const el = document.querySelector(selector);
  if (!el || !('IntersectionObserver' in window)) return;
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      trackEventOnce(`scroll:${eventName}`, eventName);
      observer.disconnect();
    });
  }, { threshold: 0, rootMargin: '0px 0px -12% 0px' });
  observer.observe(el);
}

