const SCROLL_DEPTH_MILESTONES = [25, 50, 75, 90, 100];
let highestScrollDepthTracked = 0;
function getPageScrollDepthPercent() {
  const scrollTop = window.scrollY || document.documentElement.scrollTop || 0;
  const scrollable = Math.max(1, document.documentElement.scrollHeight - window.innerHeight);
  return Math.min(100, Math.round((scrollTop / scrollable) * 100));
}
function syncScrollDepthAnalytics() {
  const depth = getPageScrollDepthPercent();
  SCROLL_DEPTH_MILESTONES.forEach(milestone => {
    if (milestone <= highestScrollDepthTracked || depth < milestone) return;
    highestScrollDepthTracked = milestone;
    trackEventOnce(`scroll-depth:${milestone}`, `scroll depth ${milestone}%`);
  });
}
window.addEventListener('scroll', syncScrollDepthAnalytics, { passive: true });
window.addEventListener('resize', syncScrollDepthAnalytics, { passive: true });
requestAnimationFrame(syncScrollDepthAnalytics);

