/* ─────────────────────────────────────────────
   INLINE HELP
───────────────────────────────────────────── */
let currentTargetEl  = null;   // element currently highlighted
let currentTipEl     = null;   // tooltip card currently shown
let resizeRAF        = null;   // requestAnimationFrame for resize debounce
 
/* ─────────────────────────────────────────────
   UTILITY: positioning the card relative to the target
   Priority order: right → top → left → bottom
   The card NEVER overlaps the target
───────────────────────────────────────────── */
const TIP_GAP    = 16;   // px between the card and ring/target
const TIP_MARGIN = 12;   // minimum margin from viewport edges
 
function positionTipCard(tipEl, targetRect) {
  if (!tipEl || !targetRect) return;
 
  /* reset previous inline position styles */
  tipEl.style.top    = '';
  tipEl.style.left   = '';
  tipEl.style.right  = '';
  tipEl.style.bottom = '';
  tipEl.style.width  = '';
  tipEl.style.maxHeight = '';
  tipEl.style.overflowY = '';
  tipEl.style.transform = '';
 
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const isNarrowShort = vw < 420 && vh <= 740;
  const isUltraNarrow = vw < 320;
  const targetIsLeftRail = targetRect.left <= 8 && targetRect.width <= 80;

  if (isNarrowShort) {
    tipEl.style.maxHeight = `calc(100vh - ${TIP_MARGIN * 2}px)`;
    tipEl.style.overflowY = 'auto';

    if (targetIsLeftRail) {
      const compactGap = isUltraNarrow ? 8 : TIP_GAP;
      const sideWidth = vw - targetRect.right - compactGap - TIP_MARGIN;
      if (sideWidth >= 150) tipEl.style.width = Math.min(280, sideWidth) + 'px';
    }
  }

  const rect = tipEl.getBoundingClientRect();
  const tw = rect.width  || 280;
  const th = Math.min(rect.height || 160, vh - TIP_MARGIN * 2);
 
  const tr = targetRect; // target rect (viewport-relative)
 
  /* 4 position options: right, top, left, bottom */
  const candidates = [
    {
      name: 'top',
      left: clamp(tr.left + tr.width / 2 - tw / 2, TIP_MARGIN, vw - tw - TIP_MARGIN),
      top:  tr.top - th - TIP_GAP,
    },
    {
      name: 'right',
      left: tr.right + TIP_GAP,
      top:  clamp(tr.top + tr.height / 2 - th / 2, TIP_MARGIN, vh - th - TIP_MARGIN),
    },
    {
      name: 'bottom',
      left: clamp(tr.left + tr.width / 2 - tw / 2, TIP_MARGIN, vw - tw - TIP_MARGIN),
      top:  tr.bottom + TIP_GAP,
    },
    {
      name: 'left',
      left: tr.left - tw - TIP_GAP,
      top:  clamp(tr.top + tr.height / 2 - th / 2, TIP_MARGIN, vh - th - TIP_MARGIN),
    },
  ];

  if (isNarrowShort && targetIsLeftRail) {
    const compactGap = isUltraNarrow ? 8 : TIP_GAP;
    candidates.find(c => c.name === 'right').left = tr.right + compactGap;
    candidates.sort((a, b) => (a.name === 'right' ? -1 : b.name === 'right' ? 1 : 0));
  }
 
  /* first option that fully fits inside the viewport */
  const chosen = candidates.find(c =>
    c.left >= TIP_MARGIN &&
    c.top  >= TIP_MARGIN &&
    c.left + tw <= vw - TIP_MARGIN &&
    c.top  + th <= vh - TIP_MARGIN
  ) || {
    name: 'viewport',
    left: clamp(candidates[0].left, TIP_MARGIN, Math.max(TIP_MARGIN, vw - tw - TIP_MARGIN)),
    top: clamp(candidates[0].top, TIP_MARGIN, Math.max(TIP_MARGIN, vh - th - TIP_MARGIN)),
  };
 
  tipEl.style.position  = 'fixed';
  tipEl.style.left      = chosen.left + 'px';
  tipEl.style.top       = chosen.top  + 'px';
  tipEl.style.transform = 'none';
}
 
function clamp(val, min, max) {
  return Math.max(min, Math.min(max, val));
}
 
/* ─────────────────────────────────────────────
   HIGHLIGHT RING — position/size update
───────────────────────────────────────────── */
function refreshCurrentTipPosition() {
  if (!currentTargetEl || !currentTipEl) return;
  positionTipCard(currentTipEl, currentTargetEl.getBoundingClientRect());
}

function settleTipPosition(times = 5, delay = 140) {
  refreshCurrentTipPosition();
  if (times <= 1) return;
  setTimeout(() => settleTipPosition(times - 1, delay), delay);
}
 
/* ─────────────────────────────────────────────
   RESIZE / SCROLL — recalculate everything
───────────────────────────────────────────── */
function onViewportChange() {
  if (!currentTargetEl || !currentTipEl) return;
  cancelAnimationFrame(resizeRAF);
  resizeRAF = requestAnimationFrame(() => {
    requestAnimationFrame(refreshCurrentTipPosition);
  });
}
 
window.addEventListener('resize', onViewportChange);
window.addEventListener('scroll', onViewportChange, { passive: true });
 
function closeNarratorForInlineHelp() {
  if (!nar || !narText) return;
  if (!nar.classList.contains('show') && !narText.childNodes.length) return;

  closeNarratorModal({ restoreFocus:false });
}

function hideInlineHelp(tipEl) {
  if (!tipEl) return;
  tipEl.classList.remove('show');
  tipEl.classList.add('is-leaving');
  setTimeout(() => {
    if (!tipEl.classList.contains('show')) {
      tipEl.classList.remove('is-leaving');
      tipEl.style.display = 'none';
    }
  }, 520);
  if (currentTipEl === tipEl) {
    currentTargetEl?.classList.remove('help-highlight');
    currentTipEl = null;
    currentTargetEl = null;
  }
}

function showAnchoredHelp(tipEl, targetEl, { trackPosition = true } = {}) {
  if (!tipEl || !targetEl) return false;
  closeNarratorForInlineHelp();
  if (currentTipEl && currentTipEl !== tipEl) {
    hideInlineHelp(currentTipEl);
  }
  currentTargetEl?.classList.remove('help-highlight');
  tipEl.style.display = '';
  tipEl.style.visibility = 'hidden';
  tipEl.classList.remove('is-leaving');
  requestAnimationFrame(() => requestAnimationFrame(() => {
    tipEl.classList.add('show');
    targetEl.classList.add('help-highlight');
    positionTipCard(tipEl, targetEl.getBoundingClientRect());
    tipEl.style.visibility = '';
    if (trackPosition) {
      currentTargetEl = targetEl;
      currentTipEl = tipEl;
      settleTipPosition();
    }
  }));
  return true;
}

