/* ─────────────────────────────────────────────
   AUDIO  (looped file with smooth fade)
───────────────────────────────────────────── */
const AMBIENT_AUDIO_SRC = './audio/cosmicMirage2.mp3';
const AMBIENT_AUDIO_TARGET_VOLUME = 0.34;
const AMBIENT_AUDIO_FADE_IN_MS = 1200;
const AMBIENT_AUDIO_FADE_OUT_MS = 760;
let ambientAudio = null;
let ambientFadeRaf = null;
let soundOn = false;
const soundBtn  = document.getElementById('btn-sound');
const soundIcon = document.getElementById('sound-icon');

function setSoundButtonState(isOn, label = '') {
  soundOn = isOn;
  soundBtn?.classList.toggle('active', isOn);
  if (soundIcon) {
    soundIcon.innerHTML = isOn
      ? '<polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/>'
      : '<polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><line x1="23" y1="9" x2="17" y2="15"/><line x1="17" y1="9" x2="23" y2="15"/>';
  }
  const labelEl = soundBtn?.querySelector('.tlabel');
  if (labelEl) labelEl.textContent = label || (isOn ? 'Sound on' : 'Sound off');
}

function getAmbientAudio() {
  if (ambientAudio) return ambientAudio;
  ambientAudio = new Audio(AMBIENT_AUDIO_SRC);
  ambientAudio.loop = true;
  ambientAudio.preload = 'auto';
  ambientAudio.volume = 0;
  ambientAudio.addEventListener('ended', () => {
    if (soundOn) {
      ambientAudio.currentTime = 0;
      ambientAudio.play?.().catch(() => {});
    }
  });
  ambientAudio.addEventListener('error', () => {
    fadeAmbientAudioTo(0, 180, true);
    setSoundButtonState(false, 'Sound unavailable');
  });
  return ambientAudio;
}

function fadeAmbientAudioTo(targetVolume, duration, pauseAfter = false) {
  const audio = getAmbientAudio();
  const fromVolume = Number.isFinite(audio.volume) ? audio.volume : 0;
  const toVolume = Math.max(0, Math.min(1, targetVolume));
  const startedAt = performance.now();
  if (ambientFadeRaf) cancelAnimationFrame(ambientFadeRaf);

  const step = now => {
    const progress = duration > 0 ? Math.min(1, (now - startedAt) / duration) : 1;
    const eased = progress < .5
      ? 2 * progress * progress
      : 1 - Math.pow(-2 * progress + 2, 2) / 2;
    audio.volume = fromVolume + (toVolume - fromVolume) * eased;

    if (progress < 1) {
      ambientFadeRaf = requestAnimationFrame(step);
      return;
    }

    ambientFadeRaf = null;
    audio.volume = toVolume;
    if (pauseAfter) audio.pause();
  };

  ambientFadeRaf = requestAnimationFrame(step);
}

async function enableAmbientAudio() {
  const audio = getAmbientAudio();
  try {
    audio.loop = true;
    audio.volume = 0;
    await audio.play();
    setSoundButtonState(true);
    fadeAmbientAudioTo(AMBIENT_AUDIO_TARGET_VOLUME, AMBIENT_AUDIO_FADE_IN_MS);
  } catch (err) {
    console.warn('Ambient audio could not start:', err);
    setSoundButtonState(false, 'Sound unavailable');
  }
}

function disableAmbientAudio() {
  setSoundButtonState(false);
  if (ambientAudio) fadeAmbientAudioTo(0, AMBIENT_AUDIO_FADE_OUT_MS, true);
}

if (soundBtn) {
  soundBtn.addEventListener('click', async () => {
    if (!soundOn) {
      await enableAmbientAudio();
    } else {
      disableAmbientAudio();
    }
  });
}

